// ── Fechas en hora Argentina ──────────────────────────────────────────────
// new Date().toISOString() devuelve UTC. Argentina es UTC-3, así que a partir
// de las 21:00 local el ISO ya está en el día siguiente: por eso los filtros de
// "Hoy" y los rangos por defecto abarcaban dos días calendario en vez de uno.
// Todo lo que sea una FECHA (no un instante) tiene que pasar por acá.
const AR_TZ = "America/Argentina/Buenos_Aires";
function fechaAR(d = new Date()) {
  // "en-CA" da directamente YYYY-MM-DD.
  return new Date(d).toLocaleDateString("en-CA", { timeZone: AR_TZ });
}
function hoyAR() { return fechaAR(); }
// Suma (o resta, con n negativo) días a una fecha "YYYY-MM-DD" sin que la zona
// horaria del navegador corra el resultado.
function sumarDiasAR(fecha, n) {
  const [y, m, d] = String(fecha).slice(0, 10).split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d) + n * 86400000).toISOString().slice(0, 10);
}

// Clave de localStorage por cuenta. Sin esto, dos cuentas que usan el mismo
// navegador comparten configuración (medidas de caja, comisiones, columnas,
// historial de exportaciones), y la segunda hereda los datos de la primera.
function ghKey(base) {
  const uid = auth.currentUser?.uid;
  return uid ? `${base}_${uid}` : base;
}

// fetch con identidad: adjunta el ID token de Firebase. Los endpoints con
// datos personales de clientes (listados de pedidos, tracking, rótulos) lo
// exigen — sin token válido devuelven 401.
async function authFetch(url, opts = {}) {
  try {
    const u = auth.currentUser;
    if (u) {
      const t = await u.getIdToken();
      opts = { ...opts, headers: { ...(opts.headers || {}), Authorization: `Bearer ${t}` } };
    }
  } catch (_) {}
  return fetch(url, opts);
}

// ── Identidad automática en TODAS las llamadas a /api/ ──────────────────────
// El backend ahora exige que el token de Firebase corresponda a la cuenta cuyos
// datos se piden (multi-tenant real). En vez de recordar poner el header en cada
// uno de los ~90 fetch de la app — donde uno olvidado rompe una sección entera —
// se adjunta acá, una sola vez. Sin sesión (portal de colaborador, que se
// autentica por token propio) no agrega nada y el request sale igual.
if (typeof window !== "undefined" && !window.__ghFetchAuth) {
  window.__ghFetchAuth = true;
  const _rawFetch = window.fetch.bind(window);
  window.fetch = async (input, init) => {
    try {
      const url = typeof input === "string" ? input : (input && input.url) || "";
      const esApi = url.startsWith("/api/") || url.includes(`${window.location.origin}/api/`);
      if (esApi && auth.currentUser) {
        const h = new Headers((init && init.headers) || (typeof input === "object" && input && input.headers) || undefined);
        if (!h.has("Authorization")) {
          h.set("Authorization", `Bearer ${await auth.currentUser.getIdToken()}`);
          init = { ...(init || {}), headers: h };
        }
      }
    } catch (_) {}
    return _rawFetch(input, init);
  };
}
// Pide al servidor el `state` firmado para el OAuth de Tienda Nube. Si algo
// falla, devuelve el uid pelado: el callback lo sigue aceptando como legacy,
// así una caída del endpoint no deja a nadie sin poder conectar su tienda.
async function ghTnState(uid) {
  try {
    const r = await fetch(`/api/integrations?platform=tiendanube&action=oauth_start`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ uid }),
    });
    const d = await r.json();
    if (d?.state) return d.state;
  } catch (_) {}
  return uid || "";
}

// ── Multi-cuenta: recordar cuentas usadas (email/nombre, NO contraseñas) para
// cambio rápido. El switch desloguea y deja un flag para pre-cargar el login. ──
// Tras un deploy, una pestaña abierta con el HTML viejo pide chunks que ya no
// existen → pantalla negra. Vite emite este evento en ese caso: recargamos solo.
if (typeof window !== "undefined") {
  window.addEventListener("vite:preloadError", () => { try { window.location.reload(); } catch(_) {} });
}

// ── Cache SWR local: pintar al instante lo último conocido y refrescar de fondo ──
// (mismo patrón que growith_envios_cache — la app "abre" en 0ms y se actualiza sola)
function ghSwrGet(key, maxAgeMs=6*3600000){ try{ const c=JSON.parse(localStorage.getItem(key)||"null"); if(c&&c.ts&&(Date.now()-c.ts)<maxAgeMs) return c.data; }catch(_){} return null; }
function ghSwrSet(key, data){ try{ localStorage.setItem(key, JSON.stringify({ts:Date.now(), data})); }catch(_){ try{localStorage.removeItem(key);}catch(__){}} }

function ghReadAccounts(){ try { return JSON.parse(localStorage.getItem("growith_accounts")||"[]"); } catch(_){ return []; } }
function ghRememberAccount(u){ if(!u?.email) return; try { const a=ghReadAccounts(); const prov=u.providerData?.[0]?.providerId||"password"; const e={email:u.email,nombre:u.displayName||u.email.split("@")[0],photoURL:u.photoURL||"",provider:prov,lastUsed:Date.now()}; const i=a.findIndex(x=>x.email===u.email); if(i>=0)a[i]={...a[i],...e}; else a.push(e); localStorage.setItem("growith_accounts",JSON.stringify(a)); } catch(_){} }
function ghForgetAccount(email){ try { localStorage.setItem("growith_accounts",JSON.stringify(ghReadAccounts().filter(x=>x.email!==email))); } catch(_){} }
async function ghSwitchAccount(email,provider){
  // Google: cambio directo con popup (sin desloguear ni pasar por el login) →
  // signInWithPopup reemplaza el usuario actual por el elegido. Casi seamless.
  if(provider==="google.com"){
    try{ const p=new GoogleAuthProvider(); if(email) p.setCustomParameters({login_hint:email,prompt:"select_account"}); await signInWithPopup(auth,p); return; }
    catch(_){ /* si falla, caemos al flujo de logout + login */ }
  }
  // Email/contraseña (o "agregar otra"): desloguea y pre-carga el login.
  try{ localStorage.setItem("growith_switch_to",JSON.stringify({email:email||"",provider:provider||""})); }catch(_){}
  signOut(auth);
}
