// --- In-app modal de confirm/alert (reemplaza window.confirm/alert) ---
let _appPromptState = null; // { kind:"confirm"|"alert", title, message, danger, okLabel, cancelLabel }
let _appPromptResolver = null;
const _appPromptListeners = new Set();
function _appPromptNotify() { _appPromptListeners.forEach(fn => fn()); }
function appConfirm(message, opts = {}) {
  return new Promise(res => {
    _appPromptState = { kind:"confirm", message, title: opts.title || "Confirmar", danger: !!opts.danger, okLabel: opts.okLabel || "Confirmar", cancelLabel: opts.cancelLabel || "Cancelar" };
    _appPromptResolver = res;
    _appPromptNotify();
  });
}
function appAlert(message, opts = {}) {
  return new Promise(res => {
    _appPromptState = { kind:"alert", message, title: opts.title || "Aviso", okLabel: opts.okLabel || "Entendido" };
    _appPromptResolver = res;
    _appPromptNotify();
  });
}
function appPrompt(message, defaultValue = "", opts = {}) {
  return new Promise(res => {
    _appPromptState = {
      kind:"prompt", message, title: opts.title || "Ingresá un valor",
      okLabel: opts.okLabel || "Aceptar", cancelLabel: opts.cancelLabel || "Cancelar",
      defaultValue, placeholder: opts.placeholder || "",
    };
    _appPromptResolver = res;
    _appPromptNotify();
  });
}
function _appPromptClose(val) {
  const r = _appPromptResolver;
  _appPromptState = null;
  _appPromptResolver = null;
  _appPromptNotify();
  if (r) r(val);
}

function AppPromptHost({ T }) {
  const [, force] = React.useState(0);
  React.useEffect(() => {
    const fn = () => force(n => n + 1);
    _appPromptListeners.add(fn);
    return () => _appPromptListeners.delete(fn);
  }, []);
  const s = _appPromptState;
  const [inputVal, setInputVal] = React.useState("");
  React.useEffect(() => { if (s?.kind === "prompt") setInputVal(s.defaultValue || ""); }, [s?.kind, s?.defaultValue]);
  // Cierre suave: al resolverse el prompt queda un snapshot ~160ms animando la salida
  const [closingState, setClosingState] = React.useState(null);
  const prevS = React.useRef(s);
  React.useEffect(() => {
    let t;
    if (!s && prevS.current) { setClosingState(prevS.current); t = setTimeout(() => setClosingState(null), 160); }
    prevS.current = s;
    return () => { if (t) clearTimeout(t); };
  });
  const shown = s || closingState;
  const closing = !s && !!closingState;
  if (!shown) return null;
  const isConfirm = shown.kind === "confirm";
  const isPromptInput = shown.kind === "prompt";
  const danger = shown.danger;
  const closeWith = (val) => { if (!closing) _appPromptClose(val); };
  const accentColor = danger ? T.red : isConfirm ? "#6366f1" : T.blue;
  const accentBg = danger ? "linear-gradient(135deg,"+T.red+","+T.red+")" : isConfirm ? "linear-gradient(135deg,#6366f1,#4f46e5)" : "linear-gradient(135deg,"+T.blue+","+T.blue+")";
  const accentTint = danger ? "rgba(239,68,68,0.13)" : isConfirm ? "rgba(99,102,241,0.13)" : "rgba(59,130,246,0.13)";
  const accentBorder = danger ? "rgba(239,68,68,0.55)" : isConfirm ? "rgba(99,102,241,0.55)" : "rgba(59,130,246,0.55)";
  const accentText = danger ? "#fca5a5" : isConfirm ? "#a5b4fc" : "#93c5fd";
  const iconPath = danger
    ? <><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z" stroke="#fff" strokeWidth="2" fill="none"/><path d="M12 9v4M12 17h.01" stroke="#fff" strokeWidth="2.5" strokeLinecap="round"/></>
    : isConfirm
    ? <><circle cx="12" cy="12" r="10" stroke="#fff" strokeWidth="2" fill="none"/><path d="M9.09 9a3 3 0 015.83 1c0 2-3 3-3 3M12 17h.01" stroke="#fff" strokeWidth="2.5" strokeLinecap="round"/></>
    : isPromptInput
    ? <><circle cx="12" cy="12" r="10" stroke="#fff" strokeWidth="2" fill="none"/><path d="M12 8v4M12 16h.01" stroke="#fff" strokeWidth="2.5" strokeLinecap="round"/></>
    : <><circle cx="12" cy="12" r="10" stroke="#fff" strokeWidth="2" fill="none"/><path d="M12 8v4M12 16h.01" stroke="#fff" strokeWidth="2.5" strokeLinecap="round"/></>;
  return ReactDOM.createPortal(
    <div className={closing?"gh-overlay-closing":"gh-overlay"} style={{position:"fixed",inset:0,zIndex:99999,background:"rgba(0,0,0,0.6)",backdropFilter:"blur(4px)",display:"flex",alignItems:"center",justifyContent:"center",padding:20,fontFamily:"'Inter',system-ui,sans-serif",pointerEvents:closing?"none":"auto"}}
      onClick={() => isConfirm ? closeWith(false) : (isPromptInput ? closeWith(null) : closeWith(true))}>
      {/* Mismo lenguaje que el resto de los modales de la app: sin barra de
          color, sin ícono gigante centrado, texto alineado a la izquierda y
          acciones abajo a la derecha. */}
      <div onClick={e => e.stopPropagation()}
        style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:16,width:"100%",maxWidth:400,boxShadow:"0 24px 64px rgba(0,0,0,0.45)",animation:closing?"growith-scaleOut 0.16s ease both":"growith-modalIn 0.2s cubic-bezier(0.4,0,0.2,1) both",overflow:"hidden"}}>
        <div style={{padding:"20px 22px 18px"}}>
          <div style={{fontSize:15,fontWeight:700,color:T.text,marginBottom:7,letterSpacing:"-0.01em"}}>{shown.title}</div>
          <div style={{fontSize:13,color:T.textMd,lineHeight:1.6,whiteSpace:"pre-wrap"}}>{shown.message}</div>
          {isPromptInput && (
            <input autoFocus type="text" value={inputVal} onChange={e=>setInputVal(e.target.value)}
              placeholder={shown.placeholder||""}
              onKeyDown={e=>{ if(e.key==="Enter") closeWith(inputVal); if(e.key==="Escape") closeWith(null); }}
              style={{width:"100%",padding:"9px 12px",fontSize:13,borderRadius:8,border:`1px solid ${T.border}`,background:T.surface,color:T.text,fontFamily:"'Inter',system-ui,sans-serif",marginTop:14,outline:"none",boxSizing:"border-box"}} />
          )}
        </div>
        <div style={{display:"flex",gap:8,justifyContent:"flex-end",padding:"12px 22px 16px",borderTop:`1px solid ${T.borderL||T.border}`}}>
          {(isConfirm || isPromptInput) && (
            <button onClick={() => closeWith(isPromptInput ? null : false)}
              style={{...BtnSecondary(T),fontSize:13,padding:"8px 16px"}}>{shown.cancelLabel}</button>
          )}
          <button autoFocus={!isPromptInput} onClick={() => closeWith(isPromptInput ? inputVal : true)}
            style={danger ? {...BtnDanger(T),fontSize:13,padding:"8px 18px",fontWeight:600} : {...BtnPrimary(T),fontSize:13,padding:"8px 18px"}}>{shown.okLabel}</button>
        </div>
      </div>
    </div>,
    document.body
  );
}

// --- DateRangePicker (dropdown con calendario inline + presets) ---
function DateRangePicker({ T, since, until, onChange, presets, onPreset }) {
  const [open, setOpen] = React.useState(false);
  // Posición fija calculada al abrir: el dropdown escapa de contenedores con
  // overflow (topbar scrolleable en mobile) y se clampa a los bordes del viewport.
  const [pos, setPos] = React.useState({top:0,right:10});
  const wrapRef = React.useRef(null);
  const ddRef = React.useRef(null); // el dropdown vive en un portal, fuera de wrapRef
  const toggleOpen = () => setOpen(o=>{
    const n=!o;
    if(n&&wrapRef.current){
      const r=wrapRef.current.getBoundingClientRect();
      const w=Math.min(340,window.innerWidth-20);
      setPos({top:r.bottom+6,right:Math.max(10,Math.min(window.innerWidth-r.right,window.innerWidth-w-10))});
    }
    return n;
  });
  const [tmpStart, setTmpStart] = React.useState(null); // primera fecha al elegir custom
  const initialMonth = (() => {
    const d = since ? new Date(since + "T00:00:00") : new Date();
    return new Date(d.getFullYear(), d.getMonth(), 1);
  })();
  const [viewMonth, setViewMonth] = React.useState(initialMonth);
  React.useEffect(() => {
    if (!open) return;
    const onDoc = (e) => { if (wrapRef.current && !wrapRef.current.contains(e.target) && !(ddRef.current && ddRef.current.contains(e.target))) setOpen(false); };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, [open]);
  const PRESETS = presets || [
    { id:"today", label:"Hoy", days:0 },
    { id:"yest", label:"Ayer", days:-1 },
    { id:"7d", label:"Últimos 7 días", days:7 },
    { id:"14d", label:"Últimos 14 días", days:14 },
    { id:"30d", label:"Últimos 30 días", days:30 },
    { id:"90d", label:"Últimos 90 días", days:90 },
  ];
  function applyPreset(p) {
    // Presets con rango explícito ("Este mes", "Mes pasado"): la función range()
    // devuelve [desde, hasta] ya resueltos — no se pueden expresar con days.
    if (p.range) { const [s,u] = p.range(); onChange(s,u); setOpen(false); return; }
    // "Hoy" y "Últimos N días" via onPreset mantienen el modo days → pegan en la
    // caché del servidor (instantáneo) en vez de un rango custom calculado en vivo.
    if (onPreset && p.days >= 0) { onPreset(p.days === 0 ? 1 : p.days); setOpen(false); return; }
    const today = new Date();
    // Zona Argentina (UTC-3) — evita el corrimiento de día que dejaba fechas mal.
    const fmt = (d) => new Intl.DateTimeFormat("en-CA",{timeZone:"America/Argentina/Buenos_Aires"}).format(d);
    if (p.days === 0) onChange(fmt(today), fmt(today));
    else if (p.days === -1) {
      const y = new Date(today.getTime() - 86400000);
      onChange(fmt(y), fmt(y));
    } else {
      onChange(fmt(new Date(today.getTime() - p.days*86400000)), fmt(today));
    }
    setOpen(false);
  }
  function clickDay(dateStr) {
    // Primer click: marca inicio. No llama onChange todavía para evitar una API call
    // con rango de 1 día que muestra datos incorrectos mientras el usuario elige el fin.
    if (!tmpStart) {
      setTmpStart(dateStr);
      return;
    }
    let s = tmpStart, u = dateStr;
    if (s > u) [s, u] = [u, s];
    onChange(s, u);
    setTmpStart(null);
    setOpen(false);
  }
  // Build month grid (Su..Sa)
  const year = viewMonth.getFullYear();
  const month = viewMonth.getMonth();
  const firstDow = new Date(year, month, 1).getDay(); // 0=Su
  const daysInMonth = new Date(year, month+1, 0).getDate();
  const daysInPrev = new Date(year, month, 0).getDate();
  const cells = [];
  for (let i=0; i<firstDow; i++) cells.push({ y:year, m:month-1, d:daysInPrev - firstDow + 1 + i, out:true });
  for (let d=1; d<=daysInMonth; d++) cells.push({ y:year, m:month, d, out:false });
  while (cells.length % 7 !== 0 || cells.length < 42) {
    const last = cells[cells.length-1];
    let yy = last.y, mm = last.m, dd = last.d + 1;
    if (last.out && mm === month-1) { /* prev month overflow before start */ }
    if (mm === month && dd > daysInMonth) { mm = month+1; dd = 1; }
    cells.push({ y:yy, m:mm, d:dd, out: mm !== month });
    if (cells.length >= 42) break;
  }
  const today = new Date(); today.setHours(0,0,0,0);
  const fmtCell = (c) => {
    const y = c.m < 0 ? c.y-1 : c.m > 11 ? c.y+1 : c.y;
    const m = ((c.m % 12) + 12) % 12;
    return `${y}-${String(m+1).padStart(2,"0")}-${String(c.d).padStart(2,"0")}`;
  };
  function inRange(str) {
    if (!since || !until) return false;
    return str >= since && str <= until;
  }
  const monthName = viewMonth.toLocaleDateString("es-AR", { month:"long", year:"numeric" });
  // Mobile: etiqueta numérica corta (dd/mm) — los nombres de mes no entran en
  // el topbar angosto y el control quedaba desbordado/desalineado.
  const trigCompacto = typeof window!=="undefined" && window.innerWidth<640;
  const fmtNum = (s)=>{const d=new Date(s+"T00:00:00");return `${String(d.getDate()).padStart(2,"0")}/${String(d.getMonth()+1).padStart(2,"0")}`;};
  const label = since && until
    ? (trigCompacto
        ? (since === until ? fmtNum(since) : `${fmtNum(since)} – ${fmtNum(until)}`)
        : (since === until
            ? new Date(since+"T00:00:00").toLocaleDateString("es-AR", { day:"numeric", month:"short", year:"numeric" })
            : `${new Date(since+"T00:00:00").toLocaleDateString("es-AR",{day:"numeric",month:"short"})} – ${new Date(until+"T00:00:00").toLocaleDateString("es-AR",{day:"numeric",month:"short",year:"numeric"})}`))
    : "Período";
  return (
    <div ref={wrapRef} style={{position:"relative",display:"inline-block",fontFamily:"'Inter',system-ui,sans-serif",flexShrink:0}}>
      <button onClick={toggleOpen} style={{display:"inline-flex",alignItems:"center",gap:trigCompacto?6:8,height:34,padding:trigCompacto?"0 10px":"0 14px",boxSizing:"border-box",background:T.input,border:`1px solid ${open?T.accent+"66":T.inputBorder}`,borderRadius:9,fontSize:12,color:T.text,cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif",whiteSpace:"nowrap"}}>
        <span style={{whiteSpace:"nowrap"}}>{label}</span> <span style={{color:T.textSm,fontSize:10}}>▾</span>
      </button>
      {open && ReactDOM.createPortal((()=>{
        /* Portal a body: si un ancestro tiene transform (animaciones con fill-mode
           both), position:fixed se vuelve relativo a ese ancestro y el calendario
           aparecía flotando en cualquier lado. En body el fixed es real.
           En mobile el dropdown anclado quedaba apretado contra el borde: se
           convierte en un bottom sheet a lo ancho con backdrop y targets táctiles. */
        const esMobile = typeof window!=="undefined" && window.innerWidth<640;
        const sheetStyle = esMobile
          ? {position:"fixed",left:10,right:10,bottom:10,zIndex:1000,background:T.card,border:`1px solid ${T.border}`,borderRadius:16,padding:16,boxShadow:"0 -10px 44px rgba(0,0,0,0.55)",boxSizing:"border-box",maxHeight:"78vh",overflowY:"auto"}
          : {position:"fixed",top:pos.top,right:pos.right,zIndex:1000,background:T.card,border:`1px solid ${T.border}`,borderRadius:12,padding:14,boxShadow:"0 14px 40px rgba(0,0,0,0.45)",width:"min(340px,calc(100vw - 20px))",boxSizing:"border-box",maxHeight:"calc(100vh - 120px)",overflowY:"auto"};
        return (<>
        {esMobile && <div onClick={()=>setOpen(false)} style={{position:"fixed",inset:0,zIndex:999,background:"rgba(0,0,0,0.45)"}}/>}
        <div ref={ddRef} className="gh-dropdown" style={sheetStyle}>
          {/* Presets */}
          <div style={{display:"grid",gridTemplateColumns:`repeat(${esMobile?2:3}, 1fr)`,gap:esMobile?8:6,marginBottom:10}}>
            {PRESETS.map(p => (
              <button key={p.id} onClick={()=>applyPreset(p)} style={{padding:esMobile?"10px 10px":"6px 10px",fontSize:esMobile?12:11,border:`1px solid ${T.border}`,borderRadius:8,background:T.surface,color:T.textMd,cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif",whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{p.label}</button>
            ))}
          </div>
          {/* Month nav */}
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}>
            <button onClick={()=>setViewMonth(new Date(year, month-1, 1))} style={{background:T.surface,border:`1px solid ${T.border}`,color:T.text,borderRadius:8,padding:"4px 10px",fontSize:12,cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif"}}>‹</button>
            <span style={{fontSize:13,fontWeight:700,color:T.text,textTransform:"capitalize"}}>{monthName}</span>
            <button onClick={()=>setViewMonth(new Date(year, month+1, 1))} style={{background:T.surface,border:`1px solid ${T.border}`,color:T.text,borderRadius:8,padding:"4px 10px",fontSize:12,cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif"}}>›</button>
          </div>
          {/* Day labels */}
          <div style={{display:"grid",gridTemplateColumns:"repeat(7, 1fr)",gap:2,marginBottom:4}}>
            {["Do","Lu","Ma","Mi","Ju","Vi","Sa"].map(d=> <div key={d} style={{textAlign:"center",fontSize:10,fontWeight:700,color:T.textSm,letterSpacing:0.3,padding:4}}>{d}</div>)}
          </div>
          {/* Day grid */}
          <div style={{display:"grid",gridTemplateColumns:"repeat(7, 1fr)",gap:2}}>
            {cells.map((c,i)=>{
              const str = fmtCell(c);
              const isToday = (()=>{ const d=new Date(str+"T00:00:00"); return d.toDateString() === today.toDateString(); })();
              const isStart = str === since;
              const isEnd = str === until;
              const isInRange = inRange(str);
              const isTmp = tmpStart && str === tmpStart;
              const dis = c.out;
              return (
                <button key={i} disabled={dis} onClick={()=>!dis && clickDay(str)} style={{
                  padding:esMobile?"10px 0":"7px 0",fontSize:esMobile?13:12,borderRadius:6,
                  border: isToday ? `1px solid ${T.accent}55` : "1px solid transparent",
                  background: isStart||isEnd||isTmp ? T.accent : isInRange ? T.accent+"22" : "transparent",
                  color: isStart||isEnd||isTmp ? "#fff" : dis ? T.textSm+"77" : T.text,
                  cursor: dis ? "default" : "pointer",
                  fontWeight: isStart||isEnd||isTmp ? 700 : 500,
                  fontFamily:"'Inter',system-ui,sans-serif",
                  opacity: dis ? 0.3 : 1,
                }}>{c.d}</button>
              );
            })}
          </div>
          {tmpStart && <div style={{marginTop:8,padding:"6px 10px",background:T.accent+"15",border:`1px solid ${T.accent}33`,borderRadius:7,fontSize:11,color:T.textMd}}>Inicio: {new Date(tmpStart+"T00:00:00").toLocaleDateString("es-AR")} — elegí la fecha final</div>}
        </div>
        </>);
      })(),
        document.body
      )}
    </div>
  );
}

// --- Helpers ---
function fmtMoney(v) { const n=parseFloat(v); if(isNaN(n)) return '--'; return '$'+n.toLocaleString('es-AR',{minimumFractionDigits:0,maximumFractionDigits:0}); }
function fmtDate(d) { if(!d) return '--'; const p=d.split(' ')[0].split('/'); if(p.length===3) return `${p[0]}/${p[1]}/${p[2]}`; return d; }
// Convierte el valor de un <input datetime-local> (hora local del navegador, sin
// zona) al instante UTC ISO que Meta interpreta sin ambigüedad. Sin esto, Meta
// tomaba "2026-05-25T21:00" como UTC y programaba los ads 3h antes (AR = UTC-3).
function localToMetaISO(s) { if(!s) return ""; const d=new Date(s); return isNaN(d.getTime()) ? s : d.toISOString(); }
function fmtTs(ts) { if(!ts?.seconds) return '--'; return new Date(ts.seconds*1000).toLocaleDateString('es-AR'); }
function fullAddress(o) { let a=o.direccion||''; if(o.dirNumero) a+=' '+o.dirNumero; if(o.piso) a+=', Piso '+o.piso; return [a,o.localidad,o.ciudad,o.cp?`CP ${o.cp}`:'',o.provincia].filter(Boolean).join(', '); }
function getLensColors(productos) { const s=new Set(); for(const p of productos){const c=SKU_LENTE[p.sku];if(c)s.add(c);} return [...s]; }
function mapEstadoEnvio(s) { return {"unpacked":"Por empaquetar","ready_to_ship":"Por enviar","shipped":"Enviado","delivered":"Entregado","unshipped":"Por empaquetar"}[s]||s||'--'; }
function mapEstadoPago(s) { return {"pending":"Pendiente","paid":"Pagado","voided":"Anulado","refunded":"Reembolsado","abandoned":"Abandonado"}[s]||s||'--'; }

function getEstadoEnvioC(T, estado) {
  const m = {
    "Por cobrar":     { dot:T.orange, bg:T.orangeBg, text:T.orange },
    "Por empaquetar": { dot:T.yellow, bg:T.yellowBg, text:T.yellow },
    "Por enviar":     { dot:T.blue,   bg:T.blueBg,   text:T.blue   },
    "Enviado":        { dot:T.purple, bg:T.purpleBg, text:T.purple },
    "Entregado":      { dot:T.green,  bg:T.greenBg,  text:T.green  },
  };
  return m[estado] || { dot:T.textSm, bg:T.borderL, text:T.textSm };
}
function getEstadoRC(T, estado) {
  const m = {
    Nuevo:               { dot:T.blue,   bg:T.blueBg,   text:T.blue   },
    Contactado:          { dot:T.yellow, bg:T.yellowBg, text:T.yellow },
    "Esperando producto":{ dot:T.orange, bg:T.orangeBg, text:T.orange },
    "Producto recibido": { dot:T.purple, bg:T.purpleBg, text:T.purple },
    "Envío en camino":   { dot:T.accent, bg:T.accentSolid+"18", text:T.accent },
    Resuelto:            { dot:T.green,  bg:T.greenBg,  text:T.green  },
    Rechazado:           { dot:T.red,    bg:T.redBg,    text:T.red    },
    // legacy
    Pendiente:           { dot:T.blue,   bg:T.blueBg,   text:T.blue   },
    "En proceso":        { dot:T.yellow, bg:T.yellowBg, text:T.yellow },
  };
  return m[estado] || { dot:T.textSm, bg:T.borderL, text:T.textSm };
}
function getEstadoCC(T, estado) {
  const m = {
    "Por enviar":          { dot:T.yellow, bg:T.yellowBg, text:T.yellow },
    "Pendiente envío":     { dot:T.yellow, bg:T.yellowBg, text:T.yellow }, // compat
    "Enviado":             { dot:T.blue,   bg:T.blueBg,   text:T.blue   },
    "Contenido pendiente": { dot:T.orange, bg:T.orangeBg, text:T.orange },
    "Contenido entregado": { dot:T.green,  bg:T.greenBg,  text:T.green  }, // compat
    "Cerrado":             { dot:T.green,  bg:T.greenBg,  text:T.green  },
    "Finalizado":          { dot:T.green,  bg:T.greenBg,  text:T.green  }, // compat
    "Cancelado":           { dot:T.red,    bg:T.redBg,    text:T.red    }, // compat
  };
  return m[estado] || { dot:T.textSm, bg:T.borderL, text:T.textSm };
}
function getTipoRC(T, tipo) {
  return tipo === "Cambio"
    ? { bg:T.purpleBg, text:T.purple }
    : { bg:T.orangeBg, text:T.orange };
}

function buildOrdersFromAPI(data) {
  if(!Array.isArray(data)) return [];
  return data.map(o=>{
    const sh=o.shipping_address||{};
    let estadoEnvio;
    const ps=o.payment_status;
    const ss=o.shipping_status;
    if(ps==="pending"||ps==="partially_paid") {
      estadoEnvio="Por cobrar";
    } else if((ps==="paid"||ps==="partially_paid"||ps==="partially_refunded")&&(ss==="unpacked"||ss==="partially_shipped"||!ss)) {
      estadoEnvio="Por empaquetar";
    } else if((ps==="paid"||ps==="partially_refunded")&&(ss==="ready_to_ship"||ss==="partially_shipped")) {
      estadoEnvio="Por enviar";
    } else if(ss==="shipped"||ss==="delivered") {
      estadoEnvio=mapEstadoEnvio(ss);
    } else {
      estadoEnvio=mapEstadoEnvio(ss);
    }
    return {
      numero:String(o.number||o.id||""),
      tnId:String(o.id||""), // id REAL de la orden en TN (para acciones como /pack)
      fecha:o.created_at?new Date(o.created_at).toLocaleDateString('es-AR'):'',
      comprador:(`${sh.name||''} ${sh.last_name||''}`.trim()||o.contact_name||o.billing_address?.name||'').trim(),
      email:o.contact_email||o.billing_address?.email||'',
      telefono:o.contact_phone||o.billing_address?.phone||'',
      dni:o.contact_identification||'',
      estadoOrden:o.status||'', estadoPago:mapEstadoPago(o.payment_status||''),
      estadoEnvio,
      total:String(o.total||''), subtotal:String(o.subtotal||''), descuento:String(o.discount||'0'),
      costoEnvio:String(o.shipping_cost_customer||'0'),
      nombreEnvio:`${sh.name||''} ${sh.last_name||''}`.trim(),
      telEnvio:o.contact_phone||'', direccion:sh.address||'', dirNumero:sh.number||'',
      piso:sh.floor||'', localidad:sh.locality||'', ciudad:sh.city||'',
      cp:sh.zipcode||'', provincia:sh.province||'',
      medioEnvio:o.shipping_option||'', medioPago:o.payment_details?.method||o.gateway_name||'',
      esSucursal:(()=>{
        const name=(o.shipping_option||'').toLowerCase();
        const fulfillName=o.fulfillments?.some(f=>{const n=(f.shipping?.option?.name||'').toLowerCase();return n.includes('sucursal')||n.includes('hop')||n.includes('retiro')||n.includes('andreani punto');});
        return fulfillName||name.includes('sucursal')||name.includes('hop')||name.includes('retiro')||name==='punto de retiro'||!!o.shipping_pickup_details||false;
      })(),
      pickupDetails:o.shipping_pickup_details||null,
      canal:o.storefront||'', tracking:o.shipping_tracking_number||'',
      linkOrden:o.admin_url||(o.id?`https://www.tiendanube.com/admin/orders/${o.id}`:""),
      fechaPago:o.paid_at||'', fechaEnvio:o.shipped_at||'',
      isPacked:!!(o.fulfillments?.some(f=>f.status==='PACKED')),
      productos:Array.isArray(o.products)?o.products.map(p=>({
        nombre:p.name||p.product_name||'',
        precio:String(p.price||p.unit_price||''),
        cantidad:String(p.quantity||'1'),
        sku:p.sku||''
      })):[],
    };
  }).sort((a,b)=>parseInt(b.numero||0)-parseInt(a.numero||0));
}

// --- Andreani shared cache (module level) ---
const _andreaniLocsCache = { current: null };

// Ubicaciones válidas del template oficial de Andreani (compartido por
// Reclamos y Canjes; AppEnvios tiene su propia copia con más lógica).
async function ghLoadAndreaniLocations() {
  if(_andreaniLocsCache.current) return _andreaniLocsCache.current;
  if(!window.JSZip){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js';s.onload=resolve;s.onerror=reject;document.head.appendChild(s);});}
  const res=await fetch('/andreani_template.xlsx?v='+Date.now());
  if(!res.ok) throw new Error("No se pudo cargar el template");
  const buf=await res.arrayBuffer();
  const zip=await window.JSZip.loadAsync(buf);
  const ssXml=await zip.file('xl/sharedStrings.xml').async('string');
  const strings=[];const rx=/<t[^>]*>([\s\S]*?)<\/t>/g;let m;while((m=rx.exec(ssXml))!==null)strings.push(m[1]);
  const locPattern=/^[A-ZÁÉÍÓÚÑÜ\s]+ \/ [A-ZÁÉÍÓÚÑÜ\s0-9]+ \/ \d+$/;
  const list=strings.filter(s=>locPattern.test(s.trim()));
  const cpIndex={};list.forEach(loc=>{const parts=loc.split(' / ');if(parts.length===3){const cp=parts[2].trim();if(!cpIndex[cp])cpIndex[cp]=[];cpIndex[cp].push(loc);}});
  const provIndex={};list.forEach(loc=>{const prov=loc.split(' / ')[0].trim();if(!provIndex[prov])provIndex[prov]=[];provIndex[prov].push(loc);});
  const sheet4Xml=await zip.file('xl/worksheets/sheet4.xml').async('string');
  const aCells=[...sheet4Xml.matchAll(/<c r="A(\d+)"[^>]*t="s"[^>]*><v>(\d+)<\/v>/g)];
  const sucursales=aCells.map(([,row,idx])=>strings[parseInt(idx)]||"").filter(s=>s.trim()&&s!=="Sucursal");
  _andreaniLocsCache.current={list,cpIndex,provIndex,sucursales};
  return _andreaniLocsCache.current;
}

// Busca UN pedido por número en la tienda (misma API que el buscador) y lo
// devuelve ya formateado, o null. Para completar el domicilio al exportar
// cuando el canje/reclamo tiene pedidoRef pero no los datos de envío.
async function ghFetchOrderByNum(uid, num) {
  const n = String(num||"").trim();
  if(!n || !uid) return null;
  try {
    const r = await authFetch(`/api/orders?uid=${uid}&q=${encodeURIComponent(n)}`);
    const data = await r.json();
    if(!Array.isArray(data)) return null;
    const built = buildOrdersFromAPI(data);
    return built.find(o=>String(o.numero)===n) || built[0] || null;
  } catch(_) { return null; }
}

// Matchea el pedido contra la lista de sucursales del template (mismo criterio
// que findAndreaniSucursal de AppEnvios): pickupDetails.name exacto → calle+nro
// del pickup → dirección de entrega. null si no hay match ÚNICO.
function ghMatchSucursal(locs, direccion, pickupDetails) {
  if(!locs.sucursales) return null;
  function n(s){ return (s||"").toUpperCase().replace(/[^A-Z0-9\s]/g,' ').replace(/\s+/g,' ').trim(); }
  if(pickupDetails){
    const tnName=n(pickupDetails.name||"");
    if(tnName){ const exact=locs.sucursales.find(s=>n(s)===tnName); if(exact) return exact; }
    const addr=(pickupDetails.address?.address||"").trim();
    const num=(pickupDetails.address?.number||"").replace(/\D.*/,"").trim();
    const query=(addr+(num?" "+num:"")).trim().toUpperCase();
    if(query.length>=3){ const r=locs.sucursales.filter(s=>s.toUpperCase().includes(query)); if(r.length===1) return r[0]; }
  } else if(direccion){
    const words=n(direccion).split(' ').filter(w=>w.length>=4);
    if(words.length>=1){ const r=locs.sucursales.filter(s=>n(s).includes(words.join(' '))); if(r.length===1) return r[0]; }
  }
  // Último intento: tokens significativos (calle + número) presentes TODOS en la
  // sucursal, sin exigir la frase exacta — TN dice "AVENIDA JURAMENTO 2385" y el
  // template puede decir "JURAMENTO 2385" o al revés.
  const STOP=new Set(["AVENIDA","AVDA","CALLE","DIAGONAL","GENERAL","GRAL","PUNTO","ANDREANI","HOP","PICKIT","SUCURSAL","S","N","SN"]);
  const src=n([pickupDetails?.name,pickupDetails?.address?.address,pickupDetails?.address?.number,(!pickupDetails&&direccion)||""].filter(Boolean).join(" "));
  const toks=[...new Set(src.split(" ").filter(w=>w&&!STOP.has(w)&&(w.length>=4||/^\d+$/.test(w))))];
  if(toks.length){
    const r=locs.sucursales.filter(s=>{const ns=n(s);return toks.every(t=>ns.includes(t));});
    if(r.length===1) return r[0];
  }
  return null;
}

// Traduce una sucursal OFICIAL de la API ({descripcion,direccion}) al string
// EXACTO del desplegable del template (o null si no existe ahí). El Excel de
// carga masiva rechaza cualquier valor fuera de su lista, aunque la sucursal
// sea real — este mapeo es obligatorio antes de escribir la columna Sucursal.
function ghTplDeOficial(locs, oficial){
  const lista=locs?.sucursales||[];
  if(!lista.length||!oficial) return null;
  const n=s=>String(s||"").toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^A-Z0-9\s]/g,' ').replace(/\s+/g,' ').trim();
  const desc=typeof oficial==="string"?oficial:(oficial.descripcion||"");
  const dir=typeof oficial==="string"?null:oficial.direccion;
  if(lista.includes(desc)) return desc;
  const mapa=new Map(lista.map(s=>[n(s),s]));
  const exacto=mapa.get(n(desc));
  if(exacto) return exacto;
  const txt=n([desc,dir?.calle,dir?.numero].filter(Boolean).join(" "));
  const STOP=new Set(["PUNTO","ANDREANI","HOP","PICKIT","SUCURSAL","ESPACIO","AVENIDA","AVDA","CALLE"]);
  const nums=[...new Set([...txt.matchAll(/\d{2,}/g)].map(x=>x[0]))];
  const words=txt.split(" ").filter(w=>w.length>=4&&!STOP.has(w)&&!/^\d+$/.test(w));
  if(!nums.length||!words.length) return null;
  const cand=lista.filter(t=>{const nt=n(t);return nums.some(x=>nt.includes(x))&&words.some(w=>nt.includes(w));});
  return cand.length===1?cand[0]:null;
}

// Tokens significativos del punto de retiro ("JURAMENTO 2385") para buscar
// en la lista oficial — sin PUNTO/ANDREANI/HOP/AVENIDA/etc.
function ghSucTokens(pickupDetails, direccion){
  const nrm=s=>String(s||"").toUpperCase().normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/[^A-Z0-9\s]/g," ").replace(/\s+/g," ").trim();
  const STOP=new Set(["PUNTO","ANDREANI","HOP","PICKIT","RETIRO","SUCURSAL","AVENIDA","AVDA","CALLE","DIAGONAL","GENERAL","GRAL","ESPACIO","DE","DEL","LA","EL"]);
  const src=nrm([pickupDetails?.name,pickupDetails?.address?.address,pickupDetails?.address?.number,(!pickupDetails&&direccion)||""].filter(Boolean).join(" "));
  return [...new Set(src.split(" ").filter(w=>w&&!STOP.has(w)&&(w.length>=4||/^\d{2,}$/.test(w))))];
}
const ghFmtDist=m=>m==null?"":m<1000?`a ${m} m`:`a ${(m/1000).toFixed(1).replace(".",",")} km`;

// XLSX de carga masiva de Andreani con UN solo envío. `o` es un pseudo-pedido
// {numero, comprador, dni, email, telefono, cp, provincia, localidad,
// direccion, dirNumero, piso, esSucursal, pickupDetails}. Si esSucursal, la
// fila va a la hoja de sucursales (col N = sucursal del template) en vez de
// la de domicilio. Tira Error si algo falla.
async function ghEtiquetaAndreaniXlsxUno(o) {
  if(!o) throw new Error("Sin datos del envío");
  const locs=await ghLoadAndreaniLocations();
  if(!window.JSZip){await new Promise((res,rej)=>{const s=document.createElement('script');s.src='https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js';s.onload=res;s.onerror=rej;document.head.appendChild(s);});}
  const tRes=await fetch('/andreani_template.xlsx?v='+Date.now());
  if(!tRes.ok) throw new Error("No se pudo cargar el template");
  const tBuf=await tRes.arrayBuffer();
  const zip=await window.JSZip.loadAsync(tBuf);
  const ssXml=await zip.file('xl/sharedStrings.xml').async('string');
  const existSS=[];const ssRx=/<t[^>]*>([\s\S]*?)<\/t>/g;let mx;while((mx=ssRx.exec(ssXml))!==null)existSS.push(mx[1]);
  const ssMap=new Map();existSS.forEach((s,i)=>ssMap.set(s,i));const newSS=[...existSS];
  function idx(s){const k=String(s==null?"":s);if(ssMap.has(k))return ssMap.get(k);const i=newSS.length;newSS.push(k);ssMap.set(k,i);return i;}
  function sC(ref,val){return '<c r="'+ref+'" t="s"><v>'+idx(val)+'</v></c>';}
  function nC(ref,val){return (val===''||val===null||val===undefined)?sC(ref,''):'<c r="'+ref+'"><v>'+val+'</v></c>';}
  // Sin tildes (Andreani rechaza caracteres fuera de ASCII) y CUIT de 11 dígitos → DNI.
  function cl(s){return String(s||"").normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[-\/\|#*]+/g,' ').replace(/[^A-Za-z0-9\s.,]/g,' ').replace(/\s{2,}/g,' ').trim();}
  // El email NO pasa por cl(): el whitelist le borraba la @ y Andreani lo
  // rechazaba como "mail inválido". Solo se sacan espacios y no-ASCII.
  function clEmail(s){return String(s||"").trim().replace(/\s+/g,'').replace(/[^\x21-\x7E]/g,'');}
  const dniDep=(()=>{const d=String(o.dni||"").replace(/\D/g,'');return d.length===11?d.slice(2,10):d;})();
  const partes=String(o.comprador||"").trim().split(' ');
  const nombre=cl(partes[0]||"");const apellido=cl(partes.slice(1).join(' ')||"");
  const tel=(o.telefono||"").replace(/[^0-9]/g,'');
  const clean0=tel.startsWith('54')?tel.slice(2):tel.startsWith('0')?tel.slice(1):tel;
  const clean=clean0.startsWith('9')&&clean0.length===10?clean0.slice(1):clean0;
  let telCod='',telNum='';
  if(clean.length>=10){telCod=clean.slice(0,clean.length-8);telNum=clean.slice(clean.length-8);}
  else if(clean.length>=8){telCod=clean.slice(0,clean.length-8)||'';telNum=clean.slice(clean.length-8);}
  else if(clean.length>0){telNum=clean;}
  const cpIndex=locs.cpIndex;const provIndex=locs.provIndex;
  const cpStr=String(o.cp||"").trim();
  const provU=(o.provincia||"").toUpperCase().replace(/^CIUDAD AUTONOMA.*/,"CAPITAL FEDERAL");
  let ubicacion="";
  const byCp=cpIndex[cpStr]||[];
  if(byCp.length>=1){const byProv=byCp.find(l=>l.startsWith(provU));ubicacion=byProv||byCp[0];}
  if(!ubicacion){const provList=provIndex[provU]||[];if(provList.length>0)ubicacion=provList[0];}
  if(!ubicacion)ubicacion=locs.list.find(l=>l.startsWith('BUENOS AIRES'))||locs.list[0]||"";
  const dirNum=String(o.dirNumero||"");
  const direccion=cl(o.direccion||"");
  // Medidas del paquete: la misma config que usa Envíos (modal "Paquete"),
  // no valores fijos. B=peso(g) C=alto D=ancho E=largo F=valor declarado.
  let pk={peso:"200",alto:"5",ancho:"5",prof:"5",valor:"6000"};
  try{const saved=localStorage.getItem(ghKey("growith_exportCfg"));if(saved)pk={...pk,...JSON.parse(saved)};}catch(_){}
  const rn=3;
  const baseCells=[sC('A'+rn,""),nC('B'+rn,parseFloat(pk.peso)||200),nC('C'+rn,parseInt(pk.alto)||5),nC('D'+rn,parseInt(pk.ancho)||5),nC('E'+rn,parseInt(pk.prof)||5),nC('F'+rn,parseFloat(pk.valor)||6000),sC('G'+rn,'#'+o.numero),sC('H'+rn,nombre),sC('I'+rn,apellido),(dniDep&&!isNaN(dniDep))?nC('J'+rn,parseFloat(dniDep)):sC('J'+rn,dniDep||""),sC('K'+rn,clEmail(o.email)),telCod?nC('L'+rn,parseFloat(telCod)):sC('L'+rn,""),telNum?nC('M'+rn,parseFloat(telNum)):sC('M'+rn,"")];
  if(o.esSucursal){
    // Envío a sucursal/punto HOP: fila en la hoja de sucursales (cols A-N,
    // N = sucursal EXACTA de la lista del template). Exportarlo a domicilio
    // mandaba el paquete a la dirección de facturación del cliente.
    // o.sucursal = elegida a mano por el usuario (selector de Canjes/Envíos).
    const sucursal=o.sucursal||ghMatchSucursal(locs, o.direccion, o.pickupDetails);
    if(!sucursal) throw new Error("es un envío a sucursal y no pude identificar cuál en la lista de Andreani — generá esta etiqueta desde Envíos, que permite elegir la sucursal a mano");
    const cells=[...baseCells,sC('N'+rn,sucursal)].join('');
    const rowXml='<row r="3" spans="1:14" x14ac:dyDescent="0.25">'+cells+'</row>';
    const sheet2file=zip.file('xl/worksheets/sheet2.xml');
    if(!sheet2file) throw new Error("el template no tiene hoja de sucursales");
    const sheet2=await sheet2file.async('string');
    const newSheet2=sheet2.replace(/<dimension ref="[^"]+"\/>/,'<dimension ref="A1:N3"/>').replace('</sheetData>',rowXml+'</sheetData>').replace(/<dataValidations[\s\S]*?<\/dataValidations>/g,'');
    zip.file('xl/worksheets/sheet2.xml',newSheet2);
  } else {
    const cells=[...baseCells,sC('N'+rn,direccion),(dirNum&&!isNaN(dirNum)&&dirNum!=='')?nC('O'+rn,parseFloat(dirNum)):nC('O'+rn,0),sC('P'+rn,cl(o.piso||"")),sC('Q'+rn,""),sC('R'+rn,ubicacion),sC('S'+rn,"")].join('');
    const rowXml='<row r="3" spans="1:19" x14ac:dyDescent="0.25">'+cells+'</row>';
    const sheet1=await zip.file('xl/worksheets/sheet1.xml').async('string');
    const newSheet1=sheet1.replace(/<dimension ref="[^"]+"\/>/,'<dimension ref="A1:S3"/>').replace('</sheetData>',rowXml+'</sheetData>').replace(/<dataValidations[\s\S]*?<\/dataValidations>/g,'');
    zip.file('xl/worksheets/sheet1.xml',newSheet1);
  }
  const newSsItems=newSS.map(s=>{const esc=s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');const sp=(s!==s.trim()||s.indexOf(String.fromCharCode(10))>=0)?' xml:space="preserve"':'';return '<si><t'+sp+'>'+esc+'</t></si>';}).join('');
  zip.file('xl/sharedStrings.xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="'+newSS.length+'" uniqueCount="'+newSS.length+'">'+newSsItems+'</sst>');
  const blob=await zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',compression:'DEFLATE'});
  const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`EnvioMasivoExcelPaquetes-${o.numero}.xlsx`;a.click();
}

// --- UI Components ---

// Inject spinner keyframe CSS once
if(typeof document!=="undefined"&&!document.getElementById("growith-spin")){
  const s=document.createElement("style");
  s.id="growith-spin";
  s.textContent=`
    /* ═══════════════════════════════════════════
       GROWITH — SISTEMA DE ANIMACIONES GLOBAL
       Todos los movimientos de la app pasan por acá.
       Durations: fast=120ms | normal=200ms | slow=320ms
       Easing: ease = cubic-bezier(0.4,0,0.2,1)
               spring = cubic-bezier(0.22,1,0.36,1)  — overshoots leve, se siente vivo
               bounce = cubic-bezier(0.34,1.56,0.64,1) — más rebote, para elementos pequeños
    ═══════════════════════════════════════════ */

    /* ── Keyframes: entradas ── */
    @keyframes growith-spin       { to { transform: rotate(360deg); } }
    @keyframes growith-fadeIn     { from{opacity:0;transform:translateY(6px)} to{opacity:1;transform:translateY(0)} }
    @keyframes growith-fadeInFast { from{opacity:0;transform:translateY(3px)} to{opacity:1;transform:translateY(0)} }
    @keyframes growith-fadeInDown { from{opacity:0;transform:translateY(-5px)} to{opacity:1;transform:translateY(0)} }
    @keyframes growith-fadeInLeft { from{opacity:0;transform:translateX(8px)} to{opacity:1;transform:translateX(0)} }
    @keyframes growith-overlayIn  { from{opacity:0} to{opacity:1} }
    @keyframes growith-scaleIn    { from{opacity:0;transform:scale(0.97)} to{opacity:1;transform:scale(1)} }
    @keyframes growith-popIn      { from{opacity:0;transform:scale(0.93) translateY(5px)} to{opacity:1;transform:scale(1) translateY(0)} }
    @keyframes growith-dropdownIn { from{opacity:0;transform:scale(0.97) translateY(-4px)} to{opacity:1;transform:scale(1) translateY(0)} }
    @keyframes growith-modalIn    { from{opacity:0;transform:scale(0.96) translateY(10px)} to{opacity:1;transform:scale(1) translateY(0)} }
    @keyframes growith-panelRight { from{opacity:0;transform:translateX(32px)} to{opacity:1;transform:translateX(0)} }
    @keyframes growith-panelUp    { from{opacity:0;transform:translateY(24px)} to{opacity:1;transform:translateY(0)} }
    @keyframes growith-slideIn    { from{opacity:0;transform:translateX(-6px)} to{opacity:1;transform:translateX(0)} }
    @keyframes slideInRight       { from{opacity:0;transform:translateX(100%)} to{opacity:1;transform:translateX(0)} }
    @keyframes growith-bounceIn   { 0%{opacity:0;transform:scale(0.4)} 55%{opacity:1;transform:scale(1.1)} 75%{transform:scale(0.94)} 100%{transform:scale(1)} }
    @keyframes growith-shimmer    { 0%{background-position:200% 0} 100%{background-position:-200% 0} }
    @keyframes growith-skeleton   { 0%,100%{opacity:0.4} 50%{opacity:0.8} }

    /* ── Keyframes: salidas ── */
    @keyframes growith-fadeOut    { from{opacity:1;transform:translateY(0)} to{opacity:0;transform:translateY(4px)} }
    @keyframes growith-scaleOut   { from{opacity:1;transform:scale(1)} to{opacity:0;transform:scale(0.96)} }
    @keyframes growith-overlayOut { from{opacity:1} to{opacity:0} }

    /* ── Keyframes: toasts ── */
    @keyframes growith-toast-in  { from{opacity:0;transform:translateY(14px) scale(0.94)} to{opacity:1;transform:translateY(0) scale(1)} }
    @keyframes growith-toast-out { from{opacity:1;transform:translateY(0) scale(1)} to{opacity:0;transform:translateY(-8px) scale(0.96)} }

    /* ── Keyframes: transición de página ── */
    @keyframes growith-pageEnter {
      from { opacity:0; transform:translateY(5px) scale(0.999); }
      to   { opacity:1; transform:none; }
    }

    /* ══════════════════════════════════════
       CLASES DE ANIMACIÓN — usar con className
    ══════════════════════════════════════ */

    /* Páginas y secciones */
    .gh-page        { animation: growith-pageEnter 0.28s cubic-bezier(0.22,1,0.36,1) both; }
    .gh-tab-content { animation: growith-fadeInFast 0.18s cubic-bezier(0.22,1,0.36,1) both; }
    .gh-section     { animation: growith-fadeIn 0.22s cubic-bezier(0.22,1,0.36,1) both; }

    /* Overlays / backdrops de modales */
    .gh-overlay, .gh-modal-backdrop {
      animation: growith-overlayIn 0.2s ease both;
    }
    .gh-overlay-closing { animation: growith-overlayOut 0.18s ease both; }

    /* Contenido de modales */
    .gh-modal   { animation: growith-modalIn 0.26s cubic-bezier(0.22,1,0.36,1) both; }
    .gh-modal-closing { animation: growith-scaleOut 0.18s ease both; }

    /* Dropdowns, popovers, menus contextuales */
    .gh-dropdown {
      animation: growith-dropdownIn 0.16s cubic-bezier(0.22,1,0.36,1) both;
      transform-origin: top center;
    }
    .gh-dropdown-up {
      animation: growith-popIn 0.16s cubic-bezier(0.22,1,0.36,1) both;
      transform-origin: bottom center;
    }

    /* Paneles laterales */
    .gh-panel-right { animation: growith-panelRight 0.28s cubic-bezier(0.22,1,0.36,1) both; }
    .gh-panel-up    { animation: growith-panelUp 0.24s cubic-bezier(0.22,1,0.36,1) both; }

    /* Accordion / detalle expandible */
    .gh-accordion   { animation: growith-fadeIn 0.2s cubic-bezier(0.22,1,0.36,1) both; }

    /* Items de lista y cards */
    .gh-list-item  { animation: growith-fadeInFast 0.18s cubic-bezier(0.22,1,0.36,1) both; }
    .gh-card-enter { animation: growith-popIn 0.22s cubic-bezier(0.22,1,0.36,1) both; }

    /* ══════════════════════════════════════
       TRANSICIONES GLOBALES DE ELEMENTOS
    ══════════════════════════════════════ */

    /* Botones — press + hover */
    button, a[role="button"] {
      transition: filter 0.14s ease, transform 0.14s cubic-bezier(0.34,1.4,0.64,1),
                  background 0.14s ease, border-color 0.14s ease,
                  box-shadow 0.16s ease, opacity 0.14s ease !important;
    }
    button:not(:disabled):hover  { filter: brightness(1.08); transform: translateY(-1px); }
    button:not(:disabled):active { transform: scale(0.95) translateY(0px) !important; filter: brightness(0.94) !important; transition-duration: 0.06s !important; }
    button:disabled { cursor: not-allowed !important; opacity: 0.38 !important; }

    /* Links */
    a { transition: opacity 0.14s ease, color 0.14s ease !important; }
    a:active { opacity: 0.65 !important; transition-duration: 0.06s !important; }

    /* Inputs */
    input, textarea, select {
      transition: border-color 0.16s ease, box-shadow 0.18s ease, background 0.16s ease !important;
    }
    input:focus, textarea:focus, select:focus {
      box-shadow: 0 0 0 3px rgba(124,58,237,0.14) !important;
      outline: none !important;
    }

    /* Cards clicables */
    .gh-clickable {
      transition: background 0.15s ease, border-color 0.15s ease,
                  transform 0.2s cubic-bezier(0.22,1,0.36,1),
                  box-shadow 0.18s ease !important;
      cursor: pointer;
    }
    .gh-clickable:hover  { transform: translateY(-2px) !important; box-shadow: 0 6px 20px rgba(0,0,0,0.12) !important; }
    .gh-clickable:active { transform: scale(0.98) translateY(0) !important; transition-duration: 0.07s !important; }

    /* Filas de tabla */
    .gh-row { transition: background 0.12s ease !important; cursor: pointer; }
    .gh-row:hover  { background: var(--gh-surface) !important; }
    .gh-row:active { background: var(--gh-card)    !important; }

    /* Kanban cards */
    .gh-kanban-card {
      transition: transform 0.2s cubic-bezier(0.22,1,0.36,1),
                  box-shadow 0.18s ease, border-color 0.14s ease !important;
    }
    .gh-kanban-card:hover { transform: translateY(-2px) !important; box-shadow: 0 6px 24px rgba(0,0,0,0.18) !important; }

    /* Tabs */
    .gh-tab {
      transition: background 0.14s ease, color 0.14s ease,
                  border-color 0.14s ease, transform 0.14s ease !important;
    }
    .gh-tab:hover  { transform: translateY(-1px) !important; }
    .gh-tab:active { transform: scale(0.96) !important; }

    /* Chips / filtros */
    .gh-chip {
      transition: background 0.14s ease, border-color 0.14s ease,
                  color 0.14s ease, transform 0.16s cubic-bezier(0.22,1,0.36,1),
                  box-shadow 0.14s ease !important;
    }
    .gh-chip:hover  { transform: translateY(-1px) !important; }
    .gh-chip:active { transform: scale(0.95) !important; }

    /* Toggle switch */
    .gh-toggle        { transition: background 0.2s ease !important; cursor: pointer; }
    .gh-toggle-thumb  { transition: left 0.22s cubic-bezier(0.34,1.3,0.64,1) !important; }

    /* Smooth scroll */
    html { scroll-behavior: smooth; }
    body { overscroll-behavior: none; transition: background 0.22s ease !important; }

    /* Selección de texto */
    ::selection { background: rgba(139,92,246,0.35); color: inherit; }

    /* Scrollbar */
    ::-webkit-scrollbar { width: 10px; height: 10px; }
    ::-webkit-scrollbar-track { background: transparent; }
    ::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.08); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
    ::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.15); background-clip: padding-box; }

    /* Focus rings */
    *:focus { outline: none; }
    button:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible, a:focus-visible {
      outline: 2px solid rgba(139,92,246,0.55);
      outline-offset: 2px;
      border-radius: 4px;
    }

    /* Hover helpers */
    .gh-hover-surface:hover { background: var(--gh-surface) !important; }
    .gh-hover-card:hover    { background: var(--gh-card)    !important; }
    .gh-hover-bg:hover      { background: var(--gh-bg)      !important; }

    /* Accordion height transition helper */
    .gh-collapse-content {
      overflow: hidden;
      transition: max-height 0.28s cubic-bezier(0.22,1,0.36,1),
                  opacity 0.22s ease;
    }

    /* Stagger helpers (nth-child delays) */
    .gh-stagger > *:nth-child(1)  { animation-delay: 0ms; }
    .gh-stagger > *:nth-child(2)  { animation-delay: 35ms; }
    .gh-stagger > *:nth-child(3)  { animation-delay: 70ms; }
    .gh-stagger > *:nth-child(4)  { animation-delay: 105ms; }
    .gh-stagger > *:nth-child(5)  { animation-delay: 140ms; }
    .gh-stagger > *:nth-child(6)  { animation-delay: 175ms; }
    .gh-stagger > *:nth-child(n+7){ animation-delay: 200ms; }
  `;
  document.head.appendChild(s);
}

// --- Toast system ---
let _toastSetters=[];
function useToast(){
  const [toasts,setToasts]=React.useState([]);
  React.useEffect(()=>{_toastSetters.push(setToasts);return()=>{_toastSetters=_toastSetters.filter(s=>s!==setToasts);};},[]);
  return toasts;
}
function toast(msg,type="success",duration=3000){
  const id=Date.now()+Math.random();
  _toastSetters.forEach(setter=>setter(prev=>[...prev,{id,msg,type}]));
  setTimeout(()=>{_toastSetters.forEach(setter=>setter(prev=>prev.filter(t=>t.id!==id)));},duration);
}
function ToastContainer({T}){
  const toasts=useToast();
  if(!toasts.length) return null;
  const cfgMap={
    success:{color:T.green,   bg:T.green, icon:<polyline points="20 6 9 17 4 12" stroke="#fff" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>},
    error:  {color:T.red,     bg:T.red, icon:<><line x1="18" y1="6" x2="6" y2="18" stroke="#fff" strokeWidth="2.5" strokeLinecap="round"/><line x1="6" y1="6" x2="18" y2="18" stroke="#fff" strokeWidth="2.5" strokeLinecap="round"/></>},
    warning:{color:T.orange||T.orange, bg:T.orange, icon:<><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z" stroke="#fff" strokeWidth="2" fill="none"/><path d="M12 9v4M12 17h.01" stroke="#fff" strokeWidth="2.5" strokeLinecap="round"/></>},
    info:   {color:T.blue||T.blue, bg:T.blue, icon:<><circle cx="12" cy="12" r="10" stroke="#fff" strokeWidth="2" fill="none"/><path d="M12 8v4M12 16h.01" stroke="#fff" strokeWidth="2.5" strokeLinecap="round"/></>},
  };
  return(
    <div style={{position:"fixed",bottom:28,left:"50%",transform:"translateX(-50%)",zIndex:9999,display:"flex",flexDirection:"column",gap:10,alignItems:"center",pointerEvents:"none"}}>
      {toasts.map(t=>{
        const cfg=cfgMap[t.type]||cfgMap.success;
        return(
          <div key={t.id} style={{
            background:`linear-gradient(135deg,${cfg.bg}14,${cfg.bg}08)`,
            border:`1.5px solid ${cfg.color}55`,
            borderLeft:`3px solid ${cfg.color}`,
            borderRadius:14,
            padding:"12px 20px 12px 14px",
            fontSize:13,fontWeight:500,color:T.text,
            fontFamily:"'Inter',system-ui,sans-serif",
            letterSpacing:"-0.01em",
            boxShadow:`0 8px 32px rgba(0,0,0,0.28), 0 0 0 1px ${cfg.color}18`,
            whiteSpace:"nowrap",display:"flex",alignItems:"center",gap:12,
            animation:"growith-toast-in 0.4s cubic-bezier(0.34,1.56,0.64,1) both",
            backdropFilter:"blur(16px)",
          }}>
            <div style={{width:28,height:28,borderRadius:8,background:`linear-gradient(135deg,${cfg.bg},${cfg.bg}cc)`,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,boxShadow:`0 4px 12px ${cfg.color}55`}}>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none">{cfg.icon}</svg>
            </div>
            {t.msg.replace(/\s*[✓✔]\s*$/, '')}
          </div>
        );
      })}
    </div>
  );
}

function Spinner({size=14,color="#fff",style={}}) {
  return (
    <span style={{display:"inline-block",width:size,height:size,border:`2px solid ${color}44`,borderTop:`2px solid ${color}`,borderRadius:"50%",animation:"growith-spin 0.7s linear infinite",flexShrink:0,...style}}/>
  );
}

// Animated page wrapper - triggers re-animation on key change
function PageView({children, pageKey, T}) {
  return (
    <div key={pageKey} className="gh-page" style={{flex:1,position:"relative"}}>
      {/* Aurora clipeada en su propio contenedor para no romper position:sticky de los hijos */}
      <div aria-hidden style={{position:"absolute",inset:0,overflow:"hidden",pointerEvents:"none",zIndex:0}}>
        <div style={{position:"absolute",top:-180,left:"50%",transform:"translateX(-50%)",width:1000,height:480,background:"radial-gradient(ellipse at center, rgba(139,92,246,0.10) 0%, transparent 65%)",filter:"blur(40px)"}}/>
        <div style={{position:"absolute",top:80,right:-120,width:420,height:420,background:"radial-gradient(circle, rgba(74,222,128,0.07) 0%, transparent 70%)",filter:"blur(60px)"}}/>
      </div>
      <div style={{position:"relative",zIndex:1,display:"flex",flexDirection:"column",minHeight:"100%"}}>
        {children}
      </div>
      {T && <AppPromptHost T={T}/>}
    </div>
  );
}

