  async function deleteTarea(tareaId) {
    if(!await appConfirm("¿Eliminar esta tarea?",{danger:true,okLabel:"Eliminar"})) return;
    // Si el backend falla, avisar con el motivo — antes el error se tragaba en
    // silencio y parecía que la tarea "no se eliminaba de verdad".
    try{
      await tareasApi({action:"deleteTarea",tareaId});
    }catch(e){
      toast("No se pudo eliminar: "+(e?.message||"error"),"error",6000);
      return;
    }
    setDatos(prev=>({...prev,tareas:prev.tareas.filter(t=>t._id!==tareaId)}));
    if(expandedTarea===tareaId) setExpandedTarea(null);
    // Cerrar también el detalle del kanban: la tarea ya no existe, no tiene
    // sentido dejar su ficha abierta.
    setKanbanSelected(prev=>prev?._id===tareaId?null:prev);
    setEditModeDetalle(false);
    toast("Tarea eliminada","warning");
  }

