  // Sube archivo DIRECTO a Meta desde el browser (sin pasar por Vercel) y
  // dispara analisis+copy automatico con Gemini. La razon de subir directo
  // es que Vercel tiene hard limit de ~4.5MB en request body, asi que un
  // video de 5-40MB no entra. Meta acepta multipart hasta 1GB.
  // Polling de status de video en Meta — corre en background apenas se
  // sube el video. Meta tarda 5-60s en procesar. Cuando termina, marca el
  // creative como video_ready=true asi al publicar no hay espera.
  async function pollVideoReady(videoId, accessToken, apiVer, creativeId) {
    const MAX_ATTEMPTS = 60; // hasta ~5 min total
    for (let i = 0; i < MAX_ATTEMPTS; i++) {
      await new Promise(r => setTimeout(r, 5000)); // poll cada 5s
      try {
        const r = await fetch(`https://graph.facebook.com/${apiVer}/${videoId}?fields=status&access_token=${encodeURIComponent(accessToken)}`);
        const j = await r.json();
        const vs = j.status?.video_status;
        if (vs === "ready") {
          setCreatives(prev => prev.map(c => c.id === creativeId ? {...c, video_ready: true, _processing: false} : c));
          // Persistir en backend para que publish lo sepa sin re-pollear
          try { await metaApi("patch_creative","PATCH",{video_ready:true},{cid:creativeId}); } catch (_) {}
          // Auto-publish: el video ya procesó del lado de Meta, si el toggle
          // está prendido y el dest está armado, disparamos publish solo.
          // Buscamos el creative fresco del state (sin _processing) y lo pasamos.
          setCreatives(prev => {
            const fresh = prev.find(c => c.id === creativeId);
            if (fresh) tryAutoPublish({...fresh, video_ready: true, _processing: false});
            return prev;
          });
          return;
        }
        if (vs === "error") {
          setCreatives(prev => prev.map(c => c.id === creativeId ? {...c, video_error: true, _processing: false} : c));
          return;
        }
      } catch (_) { /* network blip, retry */ }
    }
  }

  // Auto-publish helper — dispara publish para UN creative cuando está listo
  // (no _processing, no _error, no _uploading) si el toggle está prendido y
  // hay dest shared válido. Es idempotente: usa autoPubFiredRef para no
  // disparar dos veces por race conditions del state update.
  async function tryAutoPublish(creative) {
    if (!autoPublishEnabled) return;
    if (!creative?.id) return;
    if (studioMode !== "shared") return;
    const dest = sharedDest || {};
    if (!dest.adset_id || !dest.link) return;
    if (!creative.copy?.trim()) return; // copy manual: no publicar sin copy del usuario
    if (creative._processing || creative._uploading || creative._error || creative.video_error) return;
    if (autoPubFiredRef.current.has(creative.id)) return;
    autoPubFiredRef.current.add(creative.id);
    // Marca el creative como "publicando" para feedback visual
    setCreatives(prev => prev.map(c => c.id === creative.id ? {...c, _autoPubStatus: "publishing"} : c));
    try {
      await metaApi("patch_creative","PATCH",{adset_id:dest.adset_id,link:dest.link,cta:dest.cta||"LEARN_MORE"},{cid:creative.id}).catch(()=>{});
      const d = await metaApi("publish","POST",{creative_id:creative.id, activate: publishActiveByDefault, default_link: dest.link, default_cta: dest.cta||"LEARN_MORE"},{acc_id:activeAccId});
      if (d.error) {
        setCreatives(prev => prev.map(c => c.id === creative.id ? {...c, _autoPubStatus: "error", _autoPubError: d.error} : c));
        setAutoPubStats(s => ({ ok: s.ok, errors: [...s.errors, { filename: creative.filename, error: d.error }] }));
      } else {
        // Publicado OK — sacamos el creative de la cola al instante (mismo
        // patron que el bulk publish)
        try { await authFetch(`/api/meta?action=delete_creative&uid=${uid}&cid=${creative.id}`,{method:"DELETE"}); } catch(_) {}
        setCreatives(prev => prev.filter(c => c.id !== creative.id));
        setAutoPubStats(s => ({ ok: s.ok + 1, errors: s.errors }));
        // Registrar como single-item batch para que quede historial
        try {
          await metaApi("publish_batch_save","POST",{
            items: [{ ad_id: d.ad_id, ig_status: d.ig_status, filename: creative.filename, kind: creative.kind, status: publishActiveByDefault?"ACTIVE":"PAUSED", ok: true, error: null, creative_id: creative.id, auto: true }],
            dest_mode: "shared",
            dest,
            errors: [],
          },{acc_id:activeAccId});
          loadPublishBatches();
        } catch(_) {}
      }
    } catch (e) {
      setCreatives(prev => prev.map(c => c.id === creative.id ? {...c, _autoPubStatus: "error", _autoPubError: e.message||"error"} : c));
    }
  }

  // Subida resumable (chunked) de video a Meta. Robusta para archivos grandes
  // y conexiones lentas: parte el archivo en los chunks que Meta indica y
  // reintenta cada chunk hasta 3 veces. Reemplaza el POST único que se caía
  // con "Network error" al cortarse la conexión a mitad de subida.
  async function uploadVideoResumableToMeta(file, accessToken, apiVersion, accIdStr, onProgress) {
    const base = `https://graph.facebook.com/${apiVersion}/${accIdStr}/advideos`;
    const postForm = async (params) => {
      let lastErr;
      for (let attempt = 0; attempt < 3; attempt++) {
        try {
          const fd = new FormData();
          fd.append("access_token", accessToken);
          for (const [k, v] of Object.entries(params)) {
            if (v instanceof Blob) fd.append(k, v, file.name);
            else fd.append(k, v);
          }
          const r = await fetch(base, { method: "POST", body: fd });
          const data = await r.json().catch(() => ({}));
          if (!r.ok || data.error) throw new Error(data.error?.message || `HTTP ${r.status}`);
          return data;
        } catch (e) {
          lastErr = e;
          await new Promise(res => setTimeout(res, (attempt + 1) * 1500));
        }
      }
      throw lastErr;
    };
    // 1) Iniciar sesión de subida
    const start = await postForm({ upload_phase: "start", file_size: String(file.size) });
    const videoId = start.video_id;
    const sessionId = start.upload_session_id;
    let startOffset = parseInt(start.start_offset);
    let endOffset = parseInt(start.end_offset);
    // 2) Transferir chunks hasta cubrir todo el archivo
    while (startOffset < endOffset) {
      const chunk = file.slice(startOffset, endOffset);
      const res = await postForm({
        upload_phase: "transfer",
        upload_session_id: sessionId,
        start_offset: String(startOffset),
        video_file_chunk: chunk,
      });
      startOffset = parseInt(res.start_offset);
      endOffset = parseInt(res.end_offset);
      if (onProgress && file.size > 0) onProgress(Math.min(99, Math.round((startOffset / file.size) * 100)));
    }
    // 3) Finalizar
    await postForm({ upload_phase: "finish", upload_session_id: sessionId });
    if (onProgress) onProgress(100);
    return videoId;
  }


  // tempId = id placeholder en la cola; localPreviewUrl = blob URL preview.
  // preFetchedCreds = creds compartidas del bulk upload (evita 1 call extra
  // por archivo).
  async function handleUploadFile(file, tempId, localPreviewUrl, preFetchedCreds) {
    if(!file) return;
    if(!activeAccId) { toast("Conectá una cuenta Meta primero","warning"); if(tempId) setCreatives(prev=>prev.filter(c=>c.id!==tempId)); return; }
    const MAX = 200 * 1024 * 1024;
    if(file.size > MAX) {
      toast(`"${file.name}" muy grande (max 200MB, ${(file.size/1024/1024).toFixed(1)}MB)`,"error");
      if(tempId) setCreatives(prev=>prev.filter(c=>c.id!==tempId));
      return;
    }
    const failTemp = (msg) => {
      toast(msg,"error");
      if(tempId) setCreatives(prev=>prev.map(c=>c.id===tempId?{...c,_uploading:false,_error:msg,ia_status:"error"}:c));
    };
    try {
      // Copy manual: el usuario lo pega en la card (no se genera con IA).
      const creds = preFetchedCreds || await metaApi("upload_creds","GET",null,{acc_id:activeAccId});
      if(creds.error){ failTemp("Error: "+creds.error); return; }
      const accIdStr = creds.ad_account_id.startsWith("act_") ? creds.ad_account_id : `act_${creds.ad_account_id}`;
      const isVideo = (file.type||"").startsWith("video/") || /\.(mp4|mov|m4v|avi|webm)$/i.test(file.name);

      let up;
      if (isVideo) {
        // Fast-path: para videos chicos (<60MB) usamos POST único (multipart),
        // que es ~2-3x más rápido que el resumable chunked. Reels y ads típicos
        // pesan 5-30MB, así que entran. Si el POST único falla por timeout o
        // network blip, caemos al resumable que es más robusto.
        const VIDEO_FAST_PATH_LIMIT = 60 * 1024 * 1024;
        let videoId = null;
        if (file.size < VIDEO_FAST_PATH_LIMIT) {
          try {
            const fd = new FormData();
            fd.append("access_token", creds.access_token);
            fd.append("source", file, file.name);
            const fastUrl = `https://graph.facebook.com/${creds.api_version}/${accIdStr}/advideos`;
            const r = await fetch(fastUrl, { method: "POST", body: fd });
            const j = await r.json().catch(() => ({}));
            if (!r.ok || j.error) throw new Error(j.error?.message || `HTTP ${r.status}`);
            videoId = j.id || j.video_id || null;
          } catch (e) {
            // fast-path falló — fallback a resumable
            console.warn(`[upload] fast-path falló para ${file.name}: ${e.message}; cayendo a resumable`);
            videoId = null;
          }
        }
        if (!videoId) {
          try {
            videoId = await uploadVideoResumableToMeta(
              file, creds.access_token, creds.api_version, accIdStr,
              (pct) => { if (tempId) setCreatives(prev => prev.map(c => c.id === tempId ? { ...c, _uploadPct: pct } : c)); }
            );
          } catch (e) {
            failTemp(`Error subiendo "${file.name}": ${e.message}`);
            return;
          }
        }
        up = { kind: "video", id: videoId, url: localPreviewUrl || null };
      } else {
        const fd = new FormData();
        fd.append("access_token", creds.access_token);
        fd.append("filename", file, file.name);
        const metaUrl = `https://graph.facebook.com/${creds.api_version}/${accIdStr}/adimages`;
        try {
          const j = await new Promise((resolve, reject) => {
            const xhr = new XMLHttpRequest();
            xhr.open("POST", metaUrl, true);
            xhr.upload.onprogress = (e) => {
              if (!e.lengthComputable) return;
              const pct = Math.round((e.loaded / e.total) * 100);
              if (tempId) setCreatives(prev => prev.map(c => c.id === tempId ? { ...c, _uploadPct: pct } : c));
            };
            xhr.onload = () => {
              try {
                const data = JSON.parse(xhr.responseText);
                if (xhr.status >= 200 && xhr.status < 300 && !data.error) resolve(data);
                else reject(new Error(data.error?.message || `HTTP ${xhr.status}`));
              } catch (e) { reject(new Error(`HTTP ${xhr.status}: respuesta no-JSON`)); }
            };
            xhr.onerror = () => reject(new Error("Network error"));
            xhr.ontimeout = () => reject(new Error("Timeout"));
            xhr.send(fd);
          });
          const img = Object.values(j.images || {})[0];
          if (!img) throw new Error("Meta no devolvió image hash");
          up = { kind: "image", hash: img.hash, url: img.url, width: img.width, height: img.height };
        } catch (e) {
          failTemp(`Error subiendo "${file.name}": ${e.message}`);
          return;
        }
      }

      // add_creative: ya incluye link + cta del shared dest, evitamos un
      // patch_creative extra por archivo.
      const fileUrl = up.url || (up.id ? `meta-video://${up.id}` : "");
      const sharedLink = studioMode === "shared" ? (sharedDest.link || "") : "";
      const sharedCta = studioMode === "shared" ? (sharedDest.cta || "LEARN_MORE") : "LEARN_MORE";
      const cr = await metaApi("add_creative","POST",{
        filename: file.name,
        kind: up.kind,
        url: fileUrl,
        size: file.size,
        meta_video_id: up.id || null,
        meta_hash: up.hash || null,
        link: sharedLink,
        cta: sharedCta,
      },{acc_id:activeAccId});
      if(cr.error){ failTemp("Error guardando creative: "+cr.error); return; }
      const cWithMeta = {
        ...cr.creative,
        link: sharedLink || cr.creative.link,
        cta: sharedCta || cr.creative.cta,
        meta_hash: up.hash || null,
        meta_video_id: up.id || null,
        // Para video: marca "procesando en Meta" hasta que video_ready
        ...(isVideo ? { _processing: true } : {}),
        ...(isVideo && localPreviewUrl ? { _localPreview: localPreviewUrl } : {}),
      };

      // Copy manual: preservamos lo que el usuario ya haya tipeado en el card
      // temporal mientras se subía el archivo (sino se perdería al hacer el swap),
      // y lo persistimos en el backend con el id real.
      if (tempId) setCreatives(prev => prev.map(c => {
        if (c.id !== tempId) return c;
        const keepCopy = c.copy || "", keepTitle = c.title || "", keepDesc = c.description || "";
        if (keepCopy || keepTitle || keepDesc) {
          metaApi("patch_creative","PATCH",{copy:keepCopy,title:keepTitle,description:keepDesc},{cid:cWithMeta.id}).catch(()=>{});
        }
        return { ...cWithMeta, copy: keepCopy, title: keepTitle, description: keepDesc };
      }));
      else setCreatives(prev => [cWithMeta, ...prev]);

      // Para video: arrancar polling en background del status de procesamiento
      // en Meta. Apenas Meta termina (5-30s tipicamente) marcamos el creative
      // como video_ready=true. Asi al publicar no hay que esperar.
      if (isVideo && up.id) {
        pollVideoReady(up.id, creds.access_token, creds.api_version, cWithMeta.id);
      } else {
        // Imagen: ya está lista (no hay polling). Si auto-publish está prendido,
        // disparamos publish on-the-spot. Para video el trigger vive en
        // pollVideoReady cuando el status pasa a "ready".
        tryAutoPublish(cWithMeta);
      }
    } catch(e){
      failTemp("Error: "+(e.message||"upload falló"));
    }
  }

  // analyze_creative con retry automatico si Gemini devuelve vacio.
  async function handleAnalyzeCreative(c, opts = {}) {
    if(!c?.id) return;
    setAnalyzingCreative(c.id);
    const MAX_RETRIES = 3;
    try {
      if (opts.skip_vision) {
        // Copy random text-only — pasa product_data/url directamente para
        // no depender de loadCreative en backend (evita "creativo no
        // encontrado" en parallel upload donde Firestore puede estar lento).
        let d = null;
        for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
          const r = await authFetch(`/api/meta?action=generate_copy&uid=${uid}&cid=${c.id}`,{
            method:"POST",headers:{"Content-Type":"application/json"},
            body:JSON.stringify({
              product_data: c.product_data || "",
              url: c.link || "",
              tone: c.tone || "",
              length: c.length || "nativo",
              format: c.format || "",
              notes: c.notes || "",
            })
          });
          const txt = await r.text();
          try { d = JSON.parse(txt); } catch(_){ d = {error:`HTTP ${r.status}`}; }
          const isRecoverable = d.error && /vací|invalid|empty|parsing|JSON|encontrado/i.test(d.error);
          if (!d.error || !isRecoverable) break;
          await new Promise(r=>setTimeout(r, 800));
        }
        if(d?.error){ toast("Error copy: "+d.error,"error"); return; }
        // Backend devuelve creative completo si lo encontro, o solo copy/title/desc.
        let updated;
        if (d.creative) updated = d.creative;
        else {
          updated = { ...c, copy: d.copy, title: d.title, description: d.description, ia_status: "ok" };
          // Guardar via patch (el backend NO guardo si no encontro el creative)
          metaApi("patch_creative","PATCH",{copy:d.copy,title:d.title,description:d.description,ia_status:"ok"},{cid:c.id}).catch(()=>{});
        }
        setCreatives(prev=>prev.map(x=>x.id===c.id?updated:x));
        if(selCreative?.id === c.id) setSelCreative(updated);
        return;
      }
      const body = { cid: c.id, auto_copy: true };
      if (opts.data_base64) body.data_base64 = opts.data_base64;
      if (opts.contentType) body.contentType = opts.contentType;
      if (c.filename) body.filename = c.filename;
      let d = null;
      for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
        d = await metaApi("analyze_creative","POST",body);
        // Retry solo si Gemini devolvio empty/parsing error
        const isRecoverable = d.error && /vací|invalid|empty|parsing|JSON/i.test(d.error);
        if (!d.error || !isRecoverable) break;
        await new Promise(r=>setTimeout(r, 800));
      }
      if(d.error){ toast("Error IA: "+d.error,"error"); return; }
      const updated = d.creative || { ...c, analysis: d.analysis, ia_status: d.auto_copy ? "ok" : "analyzed", ...(d.auto_copy ? { copy: d.auto_copy.copy, title: d.auto_copy.title, description: d.auto_copy.description } : {}) };
      setCreatives(prev=>prev.map(x=>x.id===c.id?updated:x));
      if(selCreative?.id === c.id) setSelCreative(updated);
      toast(d.auto_copy ? "Análisis + copy ✓" : "Análisis listo ✓","success");
    } finally { setAnalyzingCreative(null); }
  }


  async function handlePatch(c,updates) {
    // Durante la subida el creative tiene id temporal (aún no existe en backend);
    // el copy queda en estado local y se persiste al completar la subida.
    if(!c?.id || String(c.id).startsWith("_temp")) return;
    const params=new URLSearchParams({action:"patch_creative",uid,cid:c.id});
    const d=await authFetch(`/api/meta?${params}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(updates)}).then(r=>r.json());
    if(d.error){toast(d.error,"error");return;}
    setCreatives(prev=>prev.map(x=>x.id===c.id?d.creative:x));
    setSelCreative(d.creative);
  }

  // ── Studio: abrir modal "Cambiar recursos" — trae todos los assets del token ──
  async function openResourcesModal() {
    if (!activeAccId) { toast("Conectá Meta primero","warning"); return; }
    setShowResourcesModal(true);
    setResourcesLoading(true);
    setResourcesData(null);
    try {
      const d = await metaApi("all_assets","GET",null,{acc_id:activeAccId});
      if (d.error) { toast("Error: "+d.error,"error"); setResourcesLoading(false); return; }
      setResourcesData(d);
      setResSel({
        ad_account_id: d.active?.ad_account_id || "",
        page_id: d.active?.page_id || "",
        ig_account_id: d.active?.ig_account_id || "",
        pixel_id: d.active?.pixel_id || "",
      });
    } finally { setResourcesLoading(false); }
  }
  async function saveResources() {
    if (!resourcesData) return;
    if (!resSel.ad_account_id) return toast("Elegí una cuenta publicitaria","warning");
    setResSaving(true);
    try {
      const aa = resourcesData.ad_accounts.find(a => a.id === resSel.ad_account_id);
      const pg = resourcesData.pages.find(p => p.id === resSel.page_id);
      const ig = resourcesData.ig_accounts.find(i => i.id === resSel.ig_account_id);
      const d = await metaApi("select","POST",{
        ad_account_id: resSel.ad_account_id,
        ad_account_name: aa?.name || "",
        page_id: resSel.page_id,
        page_name: pg?.name || "",
        page_access_token: pg?.access_token || "",
        ig_account_id: resSel.ig_account_id,
        ig_username: ig?.username || "",
        pixel_id: resSel.pixel_id,
        currency: aa?.currency || "",
        timezone_name: aa?.timezone_name || "",
      },{acc_id:activeAccId});
      if (d.error) { toast(d.error,"error"); setResSaving(false); return; }
      // Refrescar la cuenta activa en memoria
      const newAcc = { ...activeAcc, ...(d.account||{}) };
      setAccounts(prev => prev.map(a => a.id === activeAccId ? newAcc : a));
      toast("Recursos guardados ✓","success");
      setShowResourcesModal(false);
    } finally { setResSaving(false); }
  }

  // ── Studio: upload multiple con UX instantanea + concurrency optima ────
  // Optimizaciones:
  // 1) Cards instantaneos con preview local.
  // 2) upload_creds se pide UNA SOLA VEZ al inicio (no 1 por archivo).
  // 3) add_creative ya incluye link/cta del shared dest — no hay
  //    patch_creative extra por archivo.
  // 4) Concurrencia 2: optimo para redes residenciales.
  async function handleUploadMultiple(fileList) {
    if (!fileList || fileList.length === 0) return;
    if (!activeAccId) return toast("Conectá una cuenta Meta primero","warning");
    const files = Array.from(fileList);
    const temps = files.map(f => {
      const isVideo = (f.type||"").startsWith("video/") || /\.(mp4|mov|m4v|avi|webm)$/i.test(f.name);
      return {
        id: `_temp_${Date.now()}_${Math.random().toString(36).slice(2,8)}`,
        _isTemp: true,
        _queued: true,    // empieza en cola
        _uploading: false,
        filename: f.name,
        filename_base: f.name.replace(/\.[^.]+$/, ""),
        kind: isVideo ? "video" : "image",
        url: URL.createObjectURL(f),
        size: f.size,
        copy: "", title: "", description: "", notes: "",
        ia_status: "uploading",
      };
    });
    setCreatives(prev => [...temps, ...prev]);
    setUploadingFile(true);

    // Pre-fetch creds una sola vez
    const creds = await metaApi("upload_creds","GET",null,{acc_id:activeAccId});
    if (creds.error) {
      toast("Error: "+creds.error,"error");
      setCreatives(prev=>prev.filter(c=>!temps.some(t=>t.id===c.id)));
      setUploadingFile(false);
      return;
    }

    // Concurrencia adaptativa — subimos en paralelo agresivo para sensación
    // "al toque". Videos antes iban de a 2 → bumpeo a 5 (cada uno chunked
    // internamente, asi que aun con conexion media saturamos el upstream
    // sin colgar nada). Imagenes 6 (más livianas).
    const isVideoFile = (f) => (f.type||"").startsWith("video/") || /\.(mp4|mov|m4v|avi|webm)$/i.test(f.name);
    const videoIndices = [];
    const imageIndices = [];
    files.forEach((f, idx) => { (isVideoFile(f) ? videoIndices : imageIndices).push(idx); });
    const makeWorker = (indices) => {
      let i = 0;
      return async () => {
        while (i < indices.length) {
          const idx = indices[i++];
          setCreatives(prev => prev.map(c => c.id === temps[idx].id ? { ...c, _queued: false, _uploading: true } : c));
          await handleUploadFile(files[idx], temps[idx].id, temps[idx].url, creds);
        }
      };
    };
    const VIDEO_CONCURRENT = 8;
    const IMAGE_CONCURRENT = 8;
    const videoWorker = makeWorker(videoIndices);
    const imageWorker = makeWorker(imageIndices);
    await Promise.all([
      ...Array.from({ length: Math.min(VIDEO_CONCURRENT, videoIndices.length) }, () => videoWorker()),
      ...Array.from({ length: Math.min(IMAGE_CONCURRENT, imageIndices.length) }, () => imageWorker()),
    ]);
    setUploadingFile(false);
    toast(`${files.length} archivo${files.length===1?"":"s"} subido${files.length===1?"":"s"} ✓`,"success");
  }

  // ── Studio: crear campaña + N adsets (con bulk endpoint create_full) ──
  async function handleCreateCampaignMulti() {
    if (!newCampMulti.name.trim()) return toast("Poné nombre de campaña","warning");
    if (!Array.isArray(newCampMulti.adsets) || newCampMulti.adsets.length === 0) return toast("Agregá al menos un AdSet","warning");
    if (newCampMulti.mode === "cbo" && (!newCampMulti.daily_budget || parseFloat(newCampMulti.daily_budget) <= 0)) return toast("CBO necesita presupuesto","warning");
    if (newCampMulti.mode === "abo") {
      for (const a of newCampMulti.adsets) {
        if (!a.daily_budget || parseFloat(a.daily_budget) <= 0) return toast(`AdSet "${a.name||"sin nombre"}" sin presupuesto`,"warning");
      }
    }
    setCreatingMulti(true);
    try {
      const body = {
        name: newCampMulti.name.trim(),
        objective: newCampMulti.objective,
        mode: newCampMulti.mode,
        daily_budget: newCampMulti.mode === "cbo" ? newCampMulti.daily_budget : "",
        active: !!newCampMulti.active,
        adsets: newCampMulti.adsets.map(a => ({
          name: a.name?.trim() || "",
          daily_budget: a.daily_budget || "",
          start_time: localToMetaISO(a.start_time),
        })),
      };
      const d = await metaApi("create_full","POST",body,{acc_id:activeAccId});
      if (d.error) { toast("Error: "+d.error,"error"); setCreatingMulti(false); return; }
      const adsetCount = d.adsets?.length || 0;
      toast(`Campaña "${d.campaign_name}" + ${adsetCount} AdSet${adsetCount===1?"":"s"} ✓`,"success");
      if (d.errors?.length) toast(d.errors.join(" · "),"warning");
      // Update optimista del state local — los dropdowns ven los nuevos al toque
      // sin esperar a que loadCampaigns sincronice con Meta (que tiene un delay
      // de eventual consistency en /adsets).
      const newStatus = newCampMulti.active ? "ACTIVE" : "PAUSED";
      const newCampObj = {
        id: d.campaign_id,
        name: d.campaign_name,
        objective: newCampMulti.objective,
        status: newStatus,
        effective_status: newStatus,
        daily_budget: newCampMulti.mode === "cbo" ? Math.round(parseFloat(newCampMulti.daily_budget) * 100) : null,
      };
      const newAdsetObjs = (d.adsets || []).map((a, i) => ({
        id: a.id,
        name: a.name || newCampMulti.adsets[i]?.name || `AdSet ${i+1}`,
        campaign_id: d.campaign_id,
        status: newStatus,
        effective_status: newStatus,
        daily_budget: newCampMulti.mode === "abo" ? Math.round(parseFloat(newCampMulti.adsets[i]?.daily_budget || 0) * 100) : null,
      }));
      setCampaigns(prev => [newCampObj, ...prev.filter(c => c.id !== d.campaign_id)]);
      setAdsets(prev => [...newAdsetObjs, ...prev.filter(a => !newAdsetObjs.some(n => n.id === a.id))]);
      // Auto-seleccionar la campaña y el primer adset creado en shared dest
      if (d.campaign_id) {
        setSharedDest(p=>({...p, campaign_id:d.campaign_id, adset_id: newAdsetObjs[0]?.id || ""}));
      }
      setShowNewCampModal(false);
      // Sincronizar con Meta en background — si los IDs ya estaban localmente
      // se mergean sin pisar nada porque filtramos por id arriba.
      loadCampaigns();
    } catch (e) {
      toast("Error: "+(e.message||"falló"),"error");
    } finally { setCreatingMulti(false); }
  }

  // ── Studio: crear adset en campaña existente ──
  async function handleCreateAdsetOnly() {
    if (!newAdsetForm.campaign_id) return toast("Elegí una campaña","warning");
    if (!newAdsetForm.name.trim()) return toast("Poné nombre de AdSet","warning");
    setSavingAdset(true);
    try {
      const camp = campaigns.find(c=>c.id===newAdsetForm.campaign_id);
      const isCbo = camp && Number(camp.daily_budget) > 0;
      const d = await metaApi("create_adset","POST",{
        name: newAdsetForm.name.trim(),
        campaign_id: newAdsetForm.campaign_id,
        is_cbo: isCbo,
        daily_budget_ars: isCbo ? "" : newAdsetForm.daily_budget,
        start_time: localToMetaISO(newAdsetForm.start_time),
        active: !!newAdsetForm.active,
      },{acc_id:activeAccId});
      if (d.error) { toast(d.error,"error"); setSavingAdset(false); return; }
      toast(`AdSet "${d.name}" creado ✓`,"success");
      // Update optimista del state local — el adset nuevo aparece al toque
      const adsetStatus = newAdsetForm.active ? "ACTIVE" : "PAUSED";
      const newAdsetObj = {
        id: d.id,
        name: d.name || newAdsetForm.name,
        campaign_id: newAdsetForm.campaign_id,
        status: adsetStatus,
        effective_status: adsetStatus,
        daily_budget: isCbo ? null : Math.round(parseFloat(newAdsetForm.daily_budget || 0) * 100),
      };
      setAdsets(prev => [newAdsetObj, ...prev.filter(a => a.id !== d.id)]);
      setSharedDest(p=>({...p, campaign_id:newAdsetForm.campaign_id, adset_id:d.id}));
      setShowNewAdsetModal(false);
      loadCampaigns();
    } finally { setSavingAdset(false); }
  }

  // ── Studio: publicar todos los creatives en cola con el shared dest ──
  // Tras cada publish exitoso, borra el creative de la cola (para que nunca
  // se publique dos veces). Al final, guarda un registro del batch en
  // publish_history para mostrar abajo del Publicar tab.
  async function handleBulkPublish() {
    if (studioMode === "shared") {
      if (!sharedDest.adset_id) return toast("Elegí o creá un AdSet","warning");
      if (!sharedDest.link?.trim()) return toast("Falta URL destino","warning");
    }
    const withCopy = creatives.filter(c => c.copy?.trim() && (studioMode === "perAd" ? c.adset_id : true));
    if (withCopy.length === 0) return toast("No hay creativos con copy listos para publicar","warning");
    // Separamos los que ya terminaron de subir (publicables ya) de los que todavía
    // se están subiendo a Meta (esos se auto-publican al terminar — el usuario puede irse).
    const queue = withCopy.filter(c => !c._uploading && !c._processing && !String(c.id).startsWith("_temp"));
    const stillUploading = withCopy.length - queue.length;
    if (!await appConfirm(`Publicar ${withCopy.length} ad${withCopy.length===1?"":"s"} en Meta ${publishActiveByDefault?"ACTIVE":"PAUSED"}?${stillUploading>0?`\n\n${stillUploading} todavía se está${stillUploading===1?"":"n"} subiendo — se publicará${stillUploading===1?"":"n"} solo al terminar. Dejá la app abierta unos minutos.`:""}`,{okLabel:"Publicar"})) return;
    // Los que aún suben se auto-publican al terminar (ya tienen copy + destino).
    if (stillUploading > 0) setAutoPublishEnabled(true);
    if (queue.length === 0) { toast(`${stillUploading} ad${stillUploading===1?"":"s"} se publicará${stillUploading===1?"":"n"} solo al terminar de subir — dejá la app abierta`); return; }
    setBulkPublishing(true);
    setBulkProgress({done:0,total:queue.length,errors:[]});
    const errs = [];
    const items = new Array(queue.length); // resumen del batch (orden conservado)
    const publishedIds = [];
    let doneCount = 0;
    // Publish en paralelo: 10 workers simultaneos. Cada Vercel invocation
    // es independiente, asi que podemos mandar muchos al mismo tiempo.
    const PUBLISH_CONCURRENT = 10;
    let nextIdx = 0;
    const publishWorker = async () => {
      while (nextIdx < queue.length) {
        const i = nextIdx++;
        const c = queue[i];
        const adsetId = studioMode === "shared" ? sharedDest.adset_id : c.adset_id;
        const link = studioMode === "shared" ? sharedDest.link : c.link;
        const cta = studioMode === "shared" ? sharedDest.cta : (c.cta || "LEARN_MORE");
        let ok = false; let adId = null; let igStatus = null; let errMsg = null;
        try {
          if (studioMode === "shared") {
            await metaApi("patch_creative","PATCH",{adset_id:adsetId,link,cta},{cid:c.id});
          }
          const d = await metaApi("publish","POST",{creative_id:c.id, activate: publishActiveByDefault, default_link: link, default_cta: cta},{acc_id:activeAccId});
          if (d.error) { errs.push(`${c.filename}: ${d.error}`); errMsg = d.error; }
          else { ok = true; adId = d.ad_id; igStatus = d.ig_status; }
        } catch (e) { errs.push(`${c.filename}: ${e.message}`); errMsg = e.message; }
        items[i] = { ad_id: adId, ig_status: igStatus, filename: c.filename, kind: c.kind, status: publishActiveByDefault?"ACTIVE":"PAUSED", ok, error: errMsg, creative_id: c.id };
        if (ok) publishedIds.push(c.id);
        doneCount++;
        setBulkProgress({done:doneCount,total:queue.length,errors:errs});
      }
    };
    await Promise.all(Array.from({ length: Math.min(PUBLISH_CONCURRENT, queue.length) }, () => publishWorker()));
    // Borrar los publicados de la cola (en backend y en state local).
    if (publishedIds.length > 0) {
      await Promise.all(publishedIds.map(cid => authFetch(`/api/meta?action=delete_creative&uid=${uid}&cid=${cid}`,{method:"DELETE"}).catch(()=>{})));
      setCreatives(prev => prev.filter(x => !publishedIds.includes(x.id)));
    }
    // Guardar registro del batch
    try {
      await metaApi("publish_batch_save","POST",{
        items,
        dest_mode: studioMode,
        dest: studioMode === "shared" ? sharedDest : null,
        errors: errs,
      },{acc_id:activeAccId});
      loadPublishBatches();
    } catch (_) {}
    setBulkPublishing(false);
    if (errs.length === 0) toast(`${queue.length} ad${queue.length===1?"":"s"} publicado${queue.length===1?"":"s"} ✓`,"success");
    else toast(`${queue.length-errs.length}/${queue.length} ok, ${errs.length} con error`,"warning");
  }

  // ── Studio: reintentar los items fallados de un lote ──
  // Filtra los items ok=false del batch, busca los creatives correspondientes
  // (que NO se borraron porque solo borramos los exitosos) y reintenta el
  // publish con la misma config dest del batch.
  const [retryingBatchId, setRetryingBatchId] = useState(null);
  async function handleRetryBatch(batch) {
    const failed = (batch.items || []).filter(i => !i.ok);
    if (failed.length === 0) return toast("No hay fallados en este lote","info");
    // Match por creative_id si esta, sino por filename
    const toRetry = failed.map(item => {
      let c = null;
      if (item.creative_id) c = creatives.find(x => x.id === item.creative_id);
      if (!c) c = creatives.find(x => x.filename === item.filename);
      return c ? { item, c } : { item, c: null };
    });
    const missing = toRetry.filter(r => !r.c).length;
    const found = toRetry.filter(r => r.c);
    if (found.length === 0) {
      return appAlert(`No se encontraron los creativos en la cola. Puede que los hayas eliminado.\n\nSi querés reintentar, volvelos a subir.`);
    }
    if (!await appConfirm(`Reintentar publicar ${found.length} ${found.length===1?"ad":"ads"}${missing>0?` (${missing} ya no están en la cola)`:""}?`,{okLabel:"Reintentar"})) return;
    setRetryingBatchId(batch.id);
    const newItems = new Array(found.length);
    const newErrs = [];
    const newPublishedIds = [];
    let retryIdx = 0;
    const retryWorker = async () => {
      while (retryIdx < found.length) {
        const k = retryIdx++;
        const { c } = found[k];
        const dest = batch.dest || {};
        const adsetId = batch.dest_mode === "shared" ? dest.adset_id : c.adset_id;
        const link = batch.dest_mode === "shared" ? dest.link : c.link;
        const cta = batch.dest_mode === "shared" ? dest.cta : (c.cta || "LEARN_MORE");
        let ok = false; let adId = null; let igStatus = null; let errMsg = null;
        try {
          if (batch.dest_mode === "shared") {
            await metaApi("patch_creative","PATCH",{adset_id:adsetId,link,cta},{cid:c.id});
          }
          const d = await metaApi("publish","POST",{creative_id:c.id, activate: false, default_link: link, default_cta: cta},{acc_id:activeAccId});
          if (d.error) { newErrs.push(`${c.filename}: ${d.error}`); errMsg = d.error; }
          else { ok = true; adId = d.ad_id; igStatus = d.ig_status; }
        } catch (e) { newErrs.push(`${c.filename}: ${e.message}`); errMsg = e.message; }
        newItems[k] = { ad_id: adId, ig_status: igStatus, filename: c.filename, kind: c.kind, status: "PAUSED", ok, error: errMsg, creative_id: c.id };
        if (ok) newPublishedIds.push(c.id);
      }
    };
    await Promise.all(Array.from({ length: Math.min(10, found.length) }, () => retryWorker()));
    if (newPublishedIds.length > 0) {
      await Promise.all(newPublishedIds.map(cid => authFetch(`/api/meta?action=delete_creative&uid=${uid}&cid=${cid}`,{method:"DELETE"}).catch(()=>{})));
      setCreatives(prev => prev.filter(x => !newPublishedIds.includes(x.id)));
    }
    try {
      await metaApi("publish_batch_save","POST",{
        items: newItems,
        dest_mode: batch.dest_mode,
        dest: batch.dest,
        errors: newErrs,
      },{acc_id:activeAccId});
      loadPublishBatches();
    } catch (_) {}
    setRetryingBatchId(null);
    if (newErrs.length === 0) toast(`${found.length} ad${found.length===1?"":"s"} re-publicado${found.length===1?"":"s"} ✓`,"success");
    else toast(`${found.length-newErrs.length}/${found.length} ok, ${newErrs.length} con error`,"warning");
  }

  // ── Studio: limpiar cola (borra creatives de Growith) ──
  async function handleClearQueue() {
    if (!creatives.length) return;
    if (!await appConfirm(`¿Borrar los ${creatives.length} creativos de la cola?\n(no afecta los ya publicados en Meta)`,{danger:true,okLabel:"Borrar todo"})) return;
    for (const c of creatives) {
      try { await authFetch(`/api/meta?action=delete_creative&uid=${uid}&cid=${c.id}`,{method:"DELETE"}); } catch (_) {}
    }
    setCreatives([]);
    setSelCreative(null);
  }

  // ── Studio: borrar un solo creative de la cola ──
  async function handleDeleteCreative(c) {
    try { await authFetch(`/api/meta?action=delete_creative&uid=${uid}&cid=${c.id}`,{method:"DELETE"}); } catch (_) {}
    setCreatives(prev => prev.filter(x => x.id !== c.id));
    if (selCreative?.id === c.id) setSelCreative(null);
  }



