      const tabParam = tab ? `&tab=${tab}` : "";
      const res=await authFetch(`/api/orders?uid=${targetUid}${tabParam}`);
      const data=await res.json();
      if(!Array.isArray(data)) throw new Error("Bad response");
      const built=buildOrdersFromAPI(data);
      setOrders(built);
